window.TADABBUR_BAQARA = {"_meta":{"description":"تدبّرٌ مُسنَدٌ لسورة البقرة، يُبنى تدرّجًا آيةً آية (٢٨٦ آية) — نبدأ بأعظم مقاطعها وأكثرها تلاوةً، ثم يُكمَل بإذن الله. النصُّ من بيانات المصحف المتحقَّقة؛ هذا الملفّ يحمل المعنى المُسنَد فقط.","honesty":"هذا تدبّرٌ لا محاورة (جوابُ الله بعد كل آية خاصٌّ بالفاتحة). المعاني منقولةٌ بتصرّفٍ يسير عن ابن كثير والسعدي مع الإحالة (مأثور)، وحالُ القلب والعملُ اجتهادٌ موسوم. والتغطيةُ جزئيةٌ مصرَّحٌ بها: نُبيّن كم آيةً غطّينا من ٢٨٦، ولا نُوهم أنّها كاملة."},"n":2,"name":"البقرة","total_ayahs":286,"audio":[1,2,3,4,5,255,285,286],"passages":[{"title":"الافتتاح: صفةُ المتّقين المفلحين","range":[1,5],"theme":"من هم أهل الهدى المنتفعون بالقرآن. ولحمةُ الموضع بما قبله: قال ابن كثير نصاً: «كل سورة افتتحت بالحروف فلا بد أن يذكر فيها الانتصار للقرآن وبيان إعجازه وعظمته، وهذا معلوم بالاستقراء، وهو الواقع في تسع وعشرين سورة؛ ولهذا يقول تعالى: الم ذلك الكتاب لا ريب فيه». ولطيفةٌ تركيبية (اجتهادية): خُتمت الفاتحة بسؤال الهداية «اهدنا الصراط المستقيم»، وفُتحت البقرة بالجواب: «ذلك الكتاب لا ريب فيه هدى للمتقين»","verses":[{"n":1,"reflection":{"text":"«الم»: قال السعدي نصاً: «الأسلم فيها السكوت عن التعرض لمعناها من غير مستند شرعي، مع الجزم بأن الله تعالى لم ينزلها عبثا بل لحكمة لا نعلمها». وساق ابن كثير أقوالَ المفسّرين فيها، ثم قولَ آخرين نصُّه: «إنما ذكرت هذه الحروف في أوائل السور التي ذكرت فيها بيانا لإعجاز القرآن، وأن الخلق عاجزون عن معارضته بمثله، هذا مع أنه تركب من هذه الحروف المقطعة التي يتخاطبون بها».","source":"تفسير السعدي وابن كثير نصاً (٢:١) — النصوص الكاملة في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، والتعظيمُ لإعجاز كلامه."},"action":{"text":"قفْ عند حدّ علمك، ولا تتكلّفْ تأويلَ ما لم يُبيَّن لك."}},{"n":2,"reflection":{"text":"«لا ريب فيه»: قال السعدي نصاً: «نفي الريب عنه يستلزم ضده... فهذا الكتاب مشتمل على علم اليقين المزيل للشك والريب»، وهذه عنده قاعدة مفيدة: «أن النفي المقصود به المدح» متضمنٌ لضده وهو الكمال. وفي «هدًى»: «وحذف المعمول... لإرادة العموم، وأنه هدى لجميع مصالح الدارين». وخُصّ المتقون لأنهم «أتوا بالسبب الأكبر لحصول الهداية وهو التقوى».","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ القرآن حقٌّ لا مريةَ فيه."},"action":{"text":"اقرأ القرآن بنيّة الاهتداء لا مجرّد التلاوة، فالهدى للمتقين."}},{"n":3,"reflection":{"text":"قال السعدي نصاً: «ليس الشأن في الإيمان بالأشياء المشاهدة بالحس، فإنه لا يتميز بها المسلم من الكافر؛ إنما الشأن في الإيمان بالغيب الذي لم نره ولم نشاهده، وإنما نؤمن به لخبر الله وخبر رسوله». وفي «يقيمون»: «لم يقل: يفعلون الصلاة أو يأتون بالصلاة، لأنه لا يكفي فيها مجرد الإتيان بصورتها الظاهرة؛ فإقامة الصلاة إقامتها ظاهرا بإتمام أركانها وواجباتها وشروطها، وإقامتها باطنا بإقامة روحها وهو حضور القلب فيها». ثم الإنفاق مما رزقهم — زكاةً وصدقة.","source":"تفسير السعدي وابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين إيمان القلب وعمل الجوارح وبذل المال."},"action":{"text":"تفقّدْ صلاتك وإنفاقك اليوم — فهما ميزانُ صدق الإيمان بالغيب."}},{"n":4,"reflection":{"text":"قال السعدي نصاً: «والذين يؤمنون بما أنزل إليك: وهو القرآن والسنة»، فيؤمنون بجميع الكتب والرسل «فلا يفرقون بين أحد منهم». وخُصّت الآخرة بالذكر «لأن الإيمان باليوم الآخر أحد أركان الإيمان، ولأنه أعظم باعث على الرغبة والرهبة والعمل»، و«اليقين هو العلم التام الذي ليس فيه أدنى شك، الموجب للعمل».","source":"تفسير السعدي نصاً (٢:٤) — النص الكامل في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ الشاملُ بوحي الله كلِّه، واستحضارُ الآخرة."},"action":{"text":"اجعلْ يقينك بالآخرة حاضرًا في قرارك القادم، يهوِّن عليك ترك المعصية."}},{"n":5,"reflection":{"text":"«على هدًى من ربهم»: قال السعدي نصاً: «أتى بعلى في هذا الموضع الدالة على الاستعلاء، وفي الضلالة يأتي بفي... لأن صاحب الهدى مستعل بالهدى مرتفع به، وصاحب الضلال منغمس فيه محتقر»، والتنكير في «هدًى» للتعظيم. و«الفلاح هو الفوز بالمطلوب والنجاة من المرهوب»، و«حصر الفلاح فيهم؛ لأنه لا سبيل إلى الفلاح إلا بسلوك سبيلهم».","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ أن أكون من المفلحين، والعملُ لذلك."},"action":{"text":"قسْ نفسك على هذه الصفات الخمس، واعملْ على تكميل ما نقص منها."}}]},{"title":"الكافرون: خَتمٌ على القلوب","range":[6,7],"theme":"من أصرَّ على الكفر عنادًا بعد قيام الحجّة — فطُبع قلبُه؛ ولطيفةٌ بنيويّة: الخَتمُ فعلُ الله على القلب والسمع، والغِشاوةُ استئنافٌ على البصر","verses":[{"n":6,"reflection":{"text":"«سواء عليهم أأنذرتهم أم لم تنذرهم لا يؤمنون»: قال السعدي نصاً إنهم «اتصفوا بالكفر، وانصبغوا به، وصار وصفا لهم لازما»، فلا الإنذارُ ولا تركُه يُجدي. واللطيفةُ المغروسةُ رحمةً بالنبي ﷺ: «كأن في هذا قطعا لطمع الرسول صلى الله عليه وسلم في إيمانهم»، فيقول له ربُّه «لا تأس عليهم، ولا تذهب نفسك عليهم حسرات». وهم صنفٌ أصرّوا بعد قيامِ الحجّة، لا كلُّ من لم يؤمن بعدُ.","source":"تفسير السعدي نصاً (٢:٦) — النص الكامل في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"بين خوفِ الإصرار الذي يُطبع به على القلب، وطمأنينةِ أنّ هدايةَ الناس ليست بيدك."},"action":{"text":"إن دعوتَ إلى خيرٍ فرُدَّ، فأدِّ الذي عليك ولا تُهلِكْ نفسك حسرةً على من أبى — فالهدى بيد الله."}},{"n":7,"reflection":{"text":"«ختم الله على قلوبهم وعلى سمعهم وعلى أبصارهم غشاوة»: لطيفةٌ بنيويّةٌ اتّفق عليها لسانا التفسير — فالخَتمُ فعلُ الله على القلوب والسمع، وأمّا البصرُ فعليه غِشاوةٌ (اسمٌ مرفوعٌ، جملةٌ مستأنفة). قال ابن كثير نصاً: «الطبع يكون على القلب وعلى السمع، والغشاوة وهي الغطاء تكون على البصر». وهو عقابٌ على إعراضهم لا ابتداءً؛ قال السعدي إنما سُدّت أبوابُ الإيمان عنهم «بسبب كفرهم وجحودهم ومعاندتهم بعد ما تبين لهم الحق». وتنبيهٌ ضدّ المبالغة: وُحِّد «سمعهم» بين الجمعين لا لسرٍّ، بل — كما نصّ القرطبي — «وحده لأنه مصدر يقع للقليل والكثير».","source":"تفسير ابن كثير والسعدي والقرطبي نصاً (٢:٧) — النصوص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعظامُ عقوبة الطبع على القلب، والحذرُ من أوّلِ إعراضٍ يجرّ إليه."},"action":{"text":"أكثِرْ من «يا مقلّب القلوب ثبّت قلبي على دينك»، ولا تأمَنْ على قلبك."}}]},{"title":"المنافقون: مرضُ القلوب ومَثَلاهم","range":[8,20],"theme":"من أظهر الإيمان وأبطن الكفر. وبنيةُ المقطع مَثَلان: قال ابن كثير إنهما لصنفَي المنافقين — «قسمان: خلص، وهم المضروب لهم المثل الناري، ومنافقون يترددون» «وهم أصحاب المثل المائي، وهم أخف حالا» — وذهب الطبريُّ وكثيرون إلى أنهما لصنفٍ واحد (اختلافٌ مذكورٌ لا يُقطَع فيه)","verses":[{"n":8,"reflection":{"text":"«ومن الناس من يقول آمنا بالله وباليوم الآخر وما هم بمؤمنين»: صنفٌ ثالثٌ — المنافقون — يُظهرون الإيمان بألسنتهم ويُبطنون الكفر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من مخالفة الظاهر للباطن."},"action":{"text":"احرصْ أن يوافق سرُّك علنك، فذاك أصلُ الصدق."}},{"n":9,"reflection":{"text":"«يخادعون الله والذين آمنوا وما يخدعون إلا أنفسهم وما يشعرون»: قال السعدي إن المخادعة «أن يظهر المخادع لمن يخادعه شيئا، ويبطن خلافه»؛ ولطيفةٌ عقليّة: «المخادع إما أن ينتج خداعه ويحصل له ما يريد، أو يسلم لا له ولا عليه، وهؤلاء عاد خداعهم عليهم» — فخسروا حيث لا يخسر المخادعون عادةً، إذ «الله تعالى لا يتضرر بخداعهم» «وعباده المؤمنون لا يضرهم كيدهم».","source":"تفسير السعدي نصاً (٢:٩) — النص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ المخادعة لله لا تخفى ولا تنفع."},"action":{"text":"دعِ التصنّعَ في العبادة؛ فالله يعلم السرّ وأخفى."}},{"n":10,"reflection":{"text":"«في قلوبهم مرض فزادهم الله مرضا ولهم عذاب أليم بما كانوا يكذبون»: مرضُ الشكّ والنفاق، فزادهم اللهُ بعدله مرضًا، ولهم عذابٌ أليم بكذبهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من أن يزيد الذنبُ القلبَ مرضًا."},"action":{"text":"بادِرْ بالتوبة قبل أن يستحكم المرض في القلب."}},{"n":11,"reflection":{"text":"«وإذا قيل لهم لا تفسدوا في الأرض قالوا إنما نحن مصلحون»: إذا نُهوا عن الإفساد بالكفر والمعاصي وموالاة الأعداء زعموا أنّهم مصلحون.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تزيين النفس للباطل باسم الإصلاح."},"action":{"text":"زِنْ عملك بميزان الشرع لا بحسن ظنّك بنفسك."}},{"n":12,"reflection":{"text":"«ألا إنهم هم المفسدون ولكن لا يشعرون»: هم المفسدون حقًّا وإن ظنّوا أنفسهم مصلحين، وذلك من عمى البصيرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ البصيرة التي تُري الحقّ حقًّا."},"action":{"text":"اقبلِ النصيحةَ ولا تردَّها بدعوى أنّك على صواب."}},{"n":13,"reflection":{"text":"«وإذا قيل لهم آمنوا كما آمن الناس قالوا أنؤمن كما آمن السفهاء»: استكبروا عن مثل إيمان الصحابة وسمّوهم سفهاء، والسفهُ الحقيقيُّ صفتُهم هم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ للحقّ ولأهله، وتركُ الكبر."},"action":{"text":"لا تستصغرْ أهل الطاعة، بل اقتدِ بهم."}},{"n":14,"reflection":{"text":"«وإذا لقوا الذين آمنوا قالوا آمنا وإذا خلوا إلى شياطينهم قالوا إنا معكم إنما نحن مستهزئون»: يتلوّنون — مع المؤمنين إظهارُ إيمان، ومع رؤوس كفرهم تأكيدُ الموافقة والاستهزاء بالمؤمنين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"بغضُ التلوّن والنفاق، وحبُّ الثبات."},"action":{"text":"كنْ واحدًا في سرّك وعلنك وبين الناس جميعًا."}},{"n":15,"reflection":{"text":"«الله يستهزئ بهم ويمدهم في طغيانهم يعمهون»: استهزاءٌ حقيقيٌّ جزاءً وفاقًا لا لفظًا مجرّدًا — قال ابن كثير إنه «يجازيهم جزاء الاستهزاء، ويعاقبهم عقوبة الخداع»، كما في «وجزاء سيئة سيئة مثلها». ومن صوره كما ذكر السعدي أنه يوم القيامة «يعطيهم مع المؤمنين نورا ظاهرا، فإذا مشى المؤمنون بنورهم طفئ نور المنافقين، وبقوا في الظلمة بعد النور متحيرين، فما أعظم اليأس بعد الطمع».","source":"تفسير ابن كثير والسعدي نصاً (٢:١٥) — النصوص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الإمهال الذي يُظنّ رضًا وهو استدراج."},"action":{"text":"لا تغترَّ بإمهال الله لك على المعصية، فالمهلةُ ليست غفلة."}},{"n":16,"reflection":{"text":"«أولئك الذين اشتروا الضلالة بالهدى فما ربحت تجارتهم وما كانوا مهتدين»: استبدلوا الضلالة بالهدى، فخسرت صفقتُهم ولم يهتدوا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على ربح تجارة الآخرة."},"action":{"text":"لا تبعْ هدًى بين يديك بشهوةٍ عاجلة."}},{"n":17,"reflection":{"text":"مَثَلُ النار (لخالِص المنافقين): «كمثل الذي استوقد نارا فلما أضاءت ما حوله ذهب الله بنورهم وتركهم في ظلمات لا يبصرون» — قال ابن كثير: «وفي هذا المثل دلالة على أنهم آمنوا ثم كفروا»، ونقل عن الرازي: «لأنهم بإيمانهم اكتسبوا أولا نورا، ثم بنفاقهم ثانيا أبطلوا ذلك النور، فوقعوا في حيرة عظيمة، فإنه لا حيرة أعظم من حيرة الدين». ولطيفةُ السعدي في المآل: «فذهب ما فيها من الإشراق، وبقي ما فيها من الإحراق».","source":"تفسير ابن كثير والسعدي نصاً (٢:١٧) — النصوص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من انطفاء نور الإيمان بعد وجوده."},"action":{"text":"تعاهدْ نور إيمانك بالطاعة، فالنورُ يخبو بالمعصية."}},{"n":18,"reflection":{"text":"«صم بكم عمي فهم لا يرجعون»: صمٌّ عن سماع الحقّ، بكمٌ عن النطق به، عميٌ عن رؤيته، فلا يرجعون إلى الهدى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"سؤالُ الله سمعًا وبصرًا نافعًا."},"action":{"text":"افتحْ سمعك وقلبك للحقّ إذا جاءك ولو خالف هواك."}},{"n":19,"reflection":{"text":"مَثَلُ المطر (للمتردِّد من المنافقين، وهو «أخفّ حالًا»): «أو كصيب من السماء فيه ظلمات ورعد وبرق» — كمن أصابه مطرٌ في ليلةٍ مظلمةٍ برعدها وبرقها. والصيّبُ هو القرآن بوعده ووعيده؛ قال السعدي إنه «فيروعهم وعيده وتزعجهم وعوده»، فيسدّون آذانهم عنه كمن يخاف الصاعقة، «والله محيط بالكافرين» لا يفوتونه.","source":"تفسير ابن كثير والسعدي نصاً (٢:١٩) — النصوص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ إحاطة الله بالخلق كلِّهم."},"action":{"text":"اعلمْ أنّك في قبضة الله فلا مهربَ إلا إليه."}},{"n":20,"reflection":{"text":"«يكاد البرق يخطف أبصارهم كلما أضاء لهم مشوا فيه وإذا أظلم عليهم قاموا»: البرقُ لمعاتُ الحقّ تكاد تخطف أبصارهم؛ فإذا لمع لهم شيءٌ من الدين «مشوا فيه»، وإذا خفت «قاموا» حيارى. ورحمةٌ في التهديد: «ولو شاء الله لذهب بسمعهم وأبصارهم» الحسيّة — قال السعدي: «ففيه تحذير لهم وتخويف بالعقوبة الدنيوية ليحذروا فيرتدعوا»؛ فلم يُذهِبْها كما خَتَم على المطبوع عليهم في (٧)، إبقاءً لبابِ الرجوع.","source":"تفسير السعدي نصاً (٢:٢٠) — النص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمة السمع والبصر والهداية."},"action":{"text":"استعملْ سمعك وبصرك فيما يرضي واهبهما."}}]},{"title":"دعوةُ التوحيد والتحدّي بالقرآن","range":[21,24],"theme":"أوّلُ أمرٍ في المصحف، وإعجازُ القرآن. وحجّةُ التوحيد فيه: الإقرارُ بأنه الخالقُ الرازق يوجب إفرادَه بالعبادة — توحيدُ الربوبية دليلُ توحيد الألوهية","verses":[{"n":21,"reflection":{"text":"«يا أيها الناس اعبدوا ربكم الذي خلقكم والذين من قبلكم لعلكم تتقون»: أوّلُ أمرٍ في المصحف — العبادةُ التي خُلِق لها الناس. وفي «لعلكم تتقون» ذكر السعدي معنيين: «أنكم إذا عبدتم الله وحده، اتقيتم بذلك سخطه وعذابه»، و«أنكم إذا عبدتم الله، صرتم من المتقين»، «وكلا المعنيين صحيح، وهما متلازمان».","source":"تفسير السعدي نصاً (٢:٢١) — النص في تبويب التفاسير","grade":"ma'thur"},"names":["الرب"],"heart_state":{"text":"استحضارُ أنّ العبادة هي الغاية التي خُلقتُ لها."},"action":{"text":"اجعلْ عبادتك اليوم عن استحضارٍ لا عادة."}},{"n":22,"reflection":{"text":"«الذي جعل لكم الأرض فراشا والسماء بناء... فلا تجعلوا لله أندادا وأنتم تعلمون»: تعدادُ النعم برهانُ التوحيد. قال السعدي إن الآية «جمعت بين الأمر بعبادة الله وحده، والنهي عن عبادة ما سواه، وبيان الدليل الباهر على وجوب عبادته»؛ وهو «توحيد الربوبية المتضمن لانفراده بالخلق والرزق والتدبير، فإذا كان كل أحد مقرا بأنه ليس له شريك في ذلك، فكذلك فليكن إقراره بأن الله لا شريك له في العبادة» — «وهذا أوضح دليل عقلي على وحدانية الباري».","source":"تفسير السعدي نصاً (٢:٢٢) — النص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تدبّرُ نعم الله ليثمر توحيدَه ومحبّته."},"action":{"text":"تأمّلْ نعمةً من نعم الله عليك، ولا تصرفْ شكرها لغيره."}},{"n":23,"reflection":{"text":"«وإن كنتم في ريب مما نزلنا على عبدنا فأتوا بسورة من مثله وادعوا شهداءكم من دون الله إن كنتم صادقين»: تحدٍّ للمرتابين. و«من مثله» فيها قولان ذكرهما ابن كثير: «من مثل هذا القرآن، قاله مجاهد وقتادة واختاره ابن جرير»، وقيل «من مثل محمد» يعني رجلًا أمّيًّا مثلَه، «والصحيح الأول». ونقل حجّةً بديعة: إن بلغت معارضتُهم حدَّ الإعجاز ظهر المطلوب، وإن عجزوا مع شدّة دواعيهم لتهوين أمره «فعلى التقديرين يحصل المعجز».","source":"تفسير ابن كثير نصاً (٢:٢٣) — النص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ القرآن كلامُ الله المعجز."},"action":{"text":"أنصتْ للقرآن كأنّك تسمعه لأوّل مرّة، متدبّرًا إعجازه."}},{"n":24,"reflection":{"text":"«فإن لم تفعلوا ولن تفعلوا فاتقوا النار التي وقودها الناس والحجارة أعدت للكافرين»: عجزُهم مقطوعٌ به («ولن تفعلوا»)، وهو إخبارٌ بالغيب وقع كما أخبر؛ فليتّقوا النار المُعدّة للكافرين.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من النار الذي يحمل على الإيمان والعمل."},"action":{"text":"استعذْ بالله من النار في سجودك ودبر صلاتك."}}]},{"title":"بشرى المؤمنين، ومَثَلُ البعوضة","range":[25,27],"theme":"جزاءُ الإيمان، وحكمةُ ضرب الأمثال","verses":[{"n":25,"reflection":{"text":"«وبشر الذين آمنوا وعملوا الصالحات أن لهم جنات تجري من تحتها الأنهار» — بشارةُ أهل الإيمان والعمل الصالح بجناتٍ دائمةٍ نعيمُها، وأزواجٍ مطهّرة، وخلودٍ لا انقطاع له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في وعد الله، والعملُ لنيله."},"action":{"text":"قدِّمْ اليوم عملًا صالحًا تلقاه في جنّة الوعد."}},{"n":26,"reflection":{"text":"«إن الله لا يستحيي أن يضرب مثلا ما بعوضة فما فوقها»: قال السعدي «لاشتمال الأمثال على الحكمة وإيضاح الحق، والله لا يستحيي من الحق». والعجيب أن المثَل الواحد يزيد المؤمنين إيمانًا والكافرين كفرًا — «فسبحان من فاوت بين عباده». والمؤمن يقبله وإن لم يُدرك تفصيله «لعلمهم بأن الله لم يضربها عبثا، بل لحكمة بالغة» — وهو عينُ تسليمه في «الم».","source":"تفسير السعدي نصاً (٢:٢٦) — النص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمة الله في كلامه كلِّه."},"action":{"text":"تلقَّ ما في القرآن بالقبول، ولا تعترضْ على شيءٍ منه."}},{"n":27,"reflection":{"text":"«الذين ينقضون عهد الله من بعد ميثاقه ويقطعون ما أمر الله به أن يوصل ويفسدون في الأرض أولئك هم الخاسرون» — صفةُ الفاسقين: نقضُ العهد، وقطعُ ما أمر اللهُ بوصله (كالرحم والإيمان)، والإفسادُ في الأرض.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ بالعهد، وصلةُ ما أمر الله بوصله."},"action":{"text":"صِلْ رحمًا قطعتَها، أو أوفِ بعهدٍ أخّرتَه."}}]},{"title":"شواهدُ التوحيد: الحياةُ والبعثُ والخلق","range":[28,29],"theme":"كيف يُكفَر بمن هذه آياته","verses":[{"n":28,"reflection":{"text":"«كيف تكفرون بالله وكنتم أمواتا فأحياكم ثم يميتكم ثم يحييكم ثم إليه ترجعون»: استفهامُ إنكارٍ وتوبيخ. والأطوارُ أربعة — قال ابن كثير: كنتم عدمًا (أمواتا) فأحياكم، «ثم يبعثكم يوم القيامة فهذه حياة أخرى، فهذه ميتتان وحياتان»، وهو تفسيرُ ﴿ربنا أمتنا اثنتين وأحييتنا اثنتين﴾. وزاد السعدي طورًا بينها: «ويجازيكم في القبور». فمن كان كلُّه في تصرّف الله فكيف يكفر به؟","source":"تفسير ابن كثير والسعدي نصاً (٢:٢٨) — النصوص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ الرجوع إلى الله فيثمر الاستعداد."},"action":{"text":"تذكّرْ أنّك راجعٌ إليه، فاعملْ ليومِ اللقاء."}},{"n":29,"reflection":{"text":"«هو الذي خلق لكم ما في الأرض جميعا ثم استوى إلى السماء فسواهن سبع سماوات وهو بكل شيء عليم»: قال السعدي: «وفي هذه الآية العظيمة دليل على أن الأصل في الأشياء الإباحة والطهارة، لأنها سيقت في معرض الامتنان» (وتخرج الخبائث بدليلٍ آخر). و«استوى» عنده ثلاثةُ معانٍ في القرآن: غيرَ معدّاةٍ «معناها الكمال والتمام»، وبـ«على» بمعنى علا وارتفع، وبـ«إلى» بمعنى قصد — وهو هنا: «لما خلق تعالى الأرض قصد إلى خلق السماوات». وقُرن العلمُ بالخلق «لأن خلقه للمخلوقات أدل دليل على علمه وحكمته وقدرته».","source":"تفسير السعدي نصاً (٢:٢٩) — النص في تبويب التفاسير","grade":"ma'thur"},"names":["العليم"],"heart_state":{"text":"شكرُ تسخير ما في الأرض، ومراقبةُ العليم."},"action":{"text":"استعملْ ما سخّر اللهُ لك في طاعته لا في معصيته."}}]},{"title":"قصةُ آدم: الخلافةُ والعلمُ والسجودُ والتوبة","range":[30,39],"theme":"بدءُ الإنسان، وأصلُ العداوة، وبابُ التوبة","verses":[{"n":30,"reflection":{"text":"«وإذ قال ربك للملائكة إني جاعل في الأرض خليفة» — أخبر اللهُ الملائكةَ بخلق آدم خليفةً، فسألوا عن حكمة خلق من يفسد ويسفك الدم، فأجابهم: «إني أعلم ما لا تعلمون».","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمة الله وإن خفيت."},"action":{"text":"إذا خفيت عليك حكمةُ قضاءٍ فقلْ: الله أعلم بما لا أعلم."}},{"n":31,"reflection":{"text":"«وعلم آدم الأسماء كلها ثم عرضهم على الملائكة» — علّم اللهُ آدمَ أسماءَ الأشياء كلِّها، إظهارًا لشرف العلم وفضلِ آدم به.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ العلم النافع الذي به شرُف آدم."},"action":{"text":"تعلّمْ اليوم مسألةً في دينك؛ فالعلمُ شرفُ ابن آدم."}},{"n":32,"reflection":{"text":"«قالوا سبحانك لا علم لنا إلا ما علمتنا إنك أنت العليم الحكيم» — نزّه الملائكةُ ربَّهم، وأقرّوا بقصور علمهم وأنّ كلَّ علمٍ منه سبحانه، فهو العليم الحكيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العليم","الحكيم"],"heart_state":{"text":"التواضعُ بالعلم، ونسبتُه إلى معلّمه سبحانه."},"action":{"text":"قلْ عند ما يُشكل عليك: «لا علم لي إلا ما علّمني ربّي»."}},{"n":33,"reflection":{"text":"«قال يا آدم أنبئهم بأسمائهم» — ظهر فضلُ آدم حين أنبأهم بالأسماء، وذكّرهم اللهُ بأنّه يعلم غيبَ السماوات والأرض وما يُبدون وما يكتمون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ علم الله بالسرّ والعلن."},"action":{"text":"راقبِ الله في خلوتك كما تراقبه في جلوتك."}},{"n":34,"reflection":{"text":"«وإذ قلنا للملائكة اسجدوا لآدم فسجدوا إلا إبليس أبى واستكبر وكان من الكافرين» — سجودُ تكريمٍ لآدم، امتنع منه إبليسُ كبرًا وحسدًا، فكان كفرُه من كبره. الكبرُ أوّلُ ذنبٍ عُصي اللهُ به.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"بغضُ الكبر الذي أهلك إبليس."},"action":{"text":"اقبلِ الحقّ ممّن جاء به، ولا يمنعك كبرٌ من الرجوع إليه."}},{"n":35,"reflection":{"text":"«وقلنا يا آدم اسكن أنت وزوجك الجنة وكلا منها رغدا حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظالمين» — أباح اللهُ لهما الجنةَ ونعيمَها إلا شجرةً واحدةً، ابتلاءً واختبارًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوقوفُ عند حدود الله وإن كثُر المباح."},"action":{"text":"اترك حرامًا واحدًا اليوم لله، وإن اتّسع لك الحلال."}},{"n":36,"reflection":{"text":"«فأزلهما الشيطان عنها فأخرجهما مما كانا فيه وقلنا اهبطوا بعضكم لبعض عدو» — أزلّهما الشيطانُ بوسوسته، فأُخرجا ممّا كانا فيه من النعيم، وأُهبطوا إلى الأرض، والعداوةُ بين ابن آدم والشيطان قائمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"textual_note":{"title":"مَن أغوى آدم؟ مسألةٌ يُخطئ فيها كثيرٌ من الناس","text":"شاع على الألسنة أنّ زوجَ آدم أغوته حتى أكل من الشجرة، وأنّ الخطيئةَ بدأت منها. وهذا قولٌ لا تجد له في كتاب الله أثرًا؛ وبيانُ ذلك أنّك إذا تتبّعتَ مواضعَ القصة في القرآن — وهي ثلاثةٌ: البقرة والأعراف وطه — لم تجد المُغويَ فيها إلا الشيطان، ولم تجد الخطابَ إلا مثنًّى يستوي فيه الزوجان:\nقال تعالى: «فأزلهما الشيطان عنها فأخرجهما مما كانا فيه» (البقرة ٣٦)، وقال: «فوسوس لهما الشيطان» ثم «وقاسمهما» ثم «فدلاهما بغرور»، فلمّا وقع ما وقع «قالا ربنا ظلمنا أنفسنا» (الأعراف ٢٠-٢٣) — اعترفا معًا، ولم يُلقِ أحدُهما باللائمة على صاحبه.\nفإذا انتهيتَ إلى سورة طه وجدتَ ما هو أصرحُ من ذلك: أفرد اللهُ الضميرَ فيها، فإذا هو لآدم لا لها: «فوسوس إليه الشيطان قال يا آدم هل أدلك على شجرة الخلد» (طه ١٢٠)، ثم «وعصى آدم ربه فغوى» (طه ١٢١). فالشيطانُ قصد آدمَ نفسَه وناداه باسمه، وآدمُ هو الذي سمّاه اللهُ بالعصيان — وهذا عكسُ ما يقوله الناس.\nويُضاف إلى ذلك أنّ اسمَ «حواء» لا يَرِد في القرآن كلِّه ولا مرّةً واحدة، فمن نسب إليها ذنبًا فقد نسبه إلى من لم يُسمِّها اللهُ في كتابه أصلًا. وقد قال تعالى: «ولا تزر وازرة وزر أخرى» — فما حمّلها اللهُ وزرًا، فلا نحمِّلها نحن ما لم يُحمِّلها إيّاه.","grade":"qati","evidence":"وهذا كلُّه ممّا يستطيع القارئُ أن يتحقّق منه بنفسه: يعُدّ مواضعَ اسم «حواء» في المصحف فلا يجد له ذكرًا، ويتتبّع فاعلَ الوسوسة في مواضع القصة فلا يجده إلا الشيطان، ويقرأ الآياتِ السبعَ التي جاء فيها الخطابُ مثنًّى فيراها بعينه. ونحن قد أحصينا ذلك على نصّ المصحف (رواية حفص، قاعدة تنزيل) حرفًا حرفًا، وجعلناه ممّا يُراجَع كلّما تغيّر شيءٌ في الأداة، حتى لا تُقال هذه الكلمةُ إلا وهي صادقة.","honesty":"وليُعلَم أنّ هذا حكمٌ على نصّ القرآن وحده، لا على كتب التفسير؛ فإنّ بعض المفسّرين نقل ها هنا أخبارًا من الإسرائيليّات فيها ذكرُ دورٍ لها. وتلك أخبارٌ لا يثبت بها حكمٌ ولا تُعارَض بها دلالةُ الكتاب. والتفريقُ بين ما قاله اللهُ وما رواه الناسُ عنه هو أصلُ الأمانة في هذا الباب."},"names":[],"heart_state":{"text":"اليقظةُ لعداوة الشيطان الدائمة، والعدلُ في نسبة الذنب لأهله."},"action":{"text":"استعذْ بالله من الشيطان كلّما همَّ بك بوسوسة؛ ولا تحمِّلْ أحدًا وزرَ غيره، فالقرآنُ ما فعل."}},{"n":37,"reflection":{"text":"«فتلقى آدم من ربه كلمات فتاب عليه إنه هو التواب الرحيم» — ألهمه اللهُ كلماتِ التوبة (ربّنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكوننّ من الخاسرين)، فتاب عليه؛ فبابُ التوبة مفتوح.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":["التواب","الرحيم"],"heart_state":{"text":"الرجاءُ في توبة الله على من أذنب فتاب."},"action":{"text":"إذا أذنبتَ فبادِرْ بالتوبة كما بادر أبوك آدم، ولا تيأسْ."}},{"n":38,"reflection":{"text":"«قلنا اهبطوا منها جميعا فإما يأتينكم مني هدى فمن تبع هداي فلا خوف عليهم ولا هم يحزنون» — الهبوطُ إلى الأرض، ووعدٌ بإرسال الهدى؛ فمن اتّبعه أمِن من خوف الآخرة وحزن الدنيا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأمانُ باتّباع هدى الله المنزَّل."},"action":{"text":"الزمْ هدى الوحي، فهو أمانُك من الخوف والحزن."}},{"n":39,"reflection":{"text":"«والذين كفروا وكذبوا بآياتنا أولئك أصحاب النار هم فيها خالدون» — ومن كفر وكذّب بآيات الله فأولئك أهلُ النار خالدين فيها، في مقابل أمنِ المتّبعين للهدى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من عاقبة التكذيب، وشكرُ نعمة الاتّباع."},"action":{"text":"جدِّدْ تصديقك بآيات الله، واحذرْ ردَّ شيءٍ منها."}}]},{"title":"نداءُ بني إسرائيل: الوفاءُ والعمل","range":[40,48],"theme":"تذكيرٌ بالنعمة، وأمرٌ بالإيمان والصدق مع النفس","verses":[{"n":40,"reflection":{"text":"«يا بني إسرائيل اذكروا نعمتي التي أنعمت عليكم وأوفوا بعهدي أوف بعهدكم وإياي فارهبون» — تذكيرٌ بنعم الله، وأمرٌ بالوفاء بعهده (الإيمان واتّباع الرسول) ليفي لهم بعهده (الجزاء)، وأن يخافوه وحده.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ بعهد الله، وإفرادُه بالرهبة."},"action":{"text":"تفقّدْ عهدًا بينك وبين الله (صلاةً أو توبة) وأوفِ به."}},{"n":41,"reflection":{"text":"«وآمنوا بما أنزلت مصدقا لما معكم ولا تكونوا أول كافر به ولا تشتروا بآياتي ثمنا قليلا» — أمرٌ بالإيمان بالقرآن المصدّق لما معهم، ونهيٌ عن أن يكونوا أوّل كافرٍ به، وعن بيع آيات الله بعرضٍ زائل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ آيات الله فلا تُباع بثمن الدنيا."},"action":{"text":"لا تكتمْ حقًّا تعرفه طمعًا في دنيا أو خوفًا من لومة."}},{"n":42,"reflection":{"text":"«ولا تلبسوا الحق بالباطل وتكتموا الحق وأنتم تعلمون» — نهيٌ عن خلط الحقّ بالباطل حتى يلتبس، وعن كتمان الحقّ مع العلم به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدعُ بالحقّ صافيًا، وتركُ تمويهه."},"action":{"text":"قلِ الحقّ كما هو، ولا تخلطْه بما يُضعفه إرضاءً لأحد."}},{"n":43,"reflection":{"text":"«وأقيموا الصلاة وآتوا الزكاة واركعوا مع الراكعين» — أمرٌ بإقامة الصلاة وإيتاء الزكاة والصلاةِ في جماعة المسلمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين حقّ الله (الصلاة) وحقّ الخلق (الزكاة) والجماعة."},"action":{"text":"احرصْ على صلاة الجماعة اليوم، ولا تؤخّرْ زكاةً وجبت."}},{"n":44,"reflection":{"text":"«أتأمرون الناس بالبر وتنسون أنفسكم وأنتم تتلون الكتاب أفلا تعقلون» — توبيخُ من يأمر الناس بالخير ويترك نفسه، وهو يتلو الكتاب؛ أفلا عقلَ يمنعه من هذا التناقض؟","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"محاسبةُ النفس قبل دعوة غيرها."},"action":{"text":"ابدأْ بنفسك في كلِّ خيرٍ تدعو إليه غيرك."}},{"n":45,"reflection":{"text":"«واستعينوا بالصبر والصلاة وإنها لكبيرة إلا على الخاشعين» — الاستعانةُ بالصبر والصلاة على أمور الدين والدنيا؛ وهي ثقيلةٌ إلا على الخاشعين الذين لان لها قلبُهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العون من الله بالصبر والصلاة عند الشدائد."},"action":{"text":"إذا ضاق بك أمرٌ فقمْ إلى الصلاة واصبرْ، فهما عونُك."}},{"n":46,"reflection":{"text":"«الذين يظنون أنهم ملاقو ربهم وأنهم إليه راجعون» — الخاشعون هم الموقنون بلقاء ربّهم ورجوعهم إليه، فهان عليهم ثقلُ الطاعة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ لقاء الله يُهوّن كلَّ تكليف."},"action":{"text":"استحضرْ قبل عبادتك أنّك ستلقى الله، تخشعْ فيها."}},{"n":47,"reflection":{"text":"«يا بني إسرائيل اذكروا نعمتي التي أنعمت عليكم وأني فضلتكم على العالمين» — تذكيرٌ بتفضيلهم على عالمي زمانهم بكثرة الأنبياء والنعم، ليشكروا لا ليفخروا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ النعمة لا الاغترارُ بها."},"action":{"text":"اشكرْ نعمةً خُصصتَ بها، ولا تجعلْها سببَ كبرٍ على غيرك."}},{"n":48,"reflection":{"text":"«واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها شفاعة ولا يؤخذ منها عدل ولا هم ينصرون» — تحذيرٌ من يومٍ لا تُغني فيه نفسٌ عن نفس، ولا شفاعةَ إلا بإذنه، ولا فداءَ ولا نصير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومٍ لا ينفع فيه إلا العمل."},"action":{"text":"قدِّمْ لنفسك اليوم؛ فلن يُجزي عنك أحدٌ هناك."}}]},{"title":"نِعَمُ الله على بني إسرائيل ومقابلتُهم لها","range":[49,59],"theme":"النجاةُ من فرعون، والعجل، والتوبة، ونعمُ التِّيه","verses":[{"n":49,"reflection":{"text":"«وإذ نجيناكم من آل فرعون يسومونكم سوء العذاب يذبحون أبناءكم ويستحيون نساءكم» — تذكيرٌ بنعمة النجاة من فرعون الذي كان يذيقهم أشدّ العذاب، وفي ذلك بلاءٌ عظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمة العافية والنجاة من الظلم."},"action":{"text":"اذكرْ نعمة الأمن التي أنت فيها، فكم من مبتلًى بضدّها."}},{"n":50,"reflection":{"text":"«وإذ فرقنا بكم البحر فأنجيناكم وأغرقنا آل فرعون وأنتم تنظرون» — فلقُ البحر ونجاتُهم وإغراقُ عدوّهم وهم يشاهدون، آيةً باهرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ فرج الله يأتي عند أضيق المضايق."},"action":{"text":"إذا اشتدّ الكرب فأحسنِ الظنّ بالله، فمعه المخرج."}},{"n":51,"reflection":{"text":"«وإذ واعدنا موسى أربعين ليلة ثم اتخذتم العجل من بعده وأنتم ظالمون» — مواعدةُ موسى أربعين ليلة لإنزال التوراة، واتّخاذُهم العجلَ معبودًا بعده ظلمًا وشركًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الانتكاس عند غياب المذكِّر."},"action":{"text":"ثبِّتْ طاعتك ولو غاب من يعينك عليها؛ فالله رقيبٌ دائمًا."}},{"n":52,"reflection":{"text":"«ثم عفونا عنكم من بعد ذلك لعلكم تشكرون» — عفوُ الله عنهم بعد أعظم الذنب (الشرك) رجاءَ أن يشكروا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في عفو الله بعد التوبة، ولو عظُم الذنب."},"action":{"text":"لا تقنطْ من ذنبٍ كبير؛ فبابُ العفو مفتوح لمن تاب."}},{"n":53,"reflection":{"text":"«وإذ آتينا موسى الكتاب والفرقان لعلكم تهتدون» — إيتاءُ موسى التوراةَ التي تفرِّق بين الحقّ والباطل، هدايةً لهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمة الوحي الذي يفرّق به الحقُّ من الباطل."},"action":{"text":"اجعلْ كتاب ربّك فُرقانك حين تشتبه عليك الأمور."}},{"n":54,"reflection":{"text":"«وإذ قال موسى لقومه يا قوم إنكم ظلمتم أنفسكم باتخاذكم العجل فتوبوا إلى بارئكم فاقتلوا أنفسكم» — أمرُهم بتوبةٍ عظيمة: أن يقتل بعضُهم بعضًا، فتاب عليهم؛ إنّه التواب الرحيم.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":["التواب","الرحيم"],"heart_state":{"text":"صدقُ التوبة ولو ثقُلت، فعاقبتُها الرحمة."},"action":{"text":"اصدقْ في توبتك ولو كلّفتك مشقّة؛ فعاقبتُها العفو."}},{"n":55,"reflection":{"text":"«وإذ قلتم يا موسى لن نؤمن لك حتى نرى الله جهرة فأخذتكم الصاعقة وأنتم تنظرون» — تعنّتُهم بطلب رؤية الله عيانًا في الدنيا، فأخذتهم الصاعقة جزاءَ جرأتهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الأدبُ مع الله، وتركُ التعنّت في الدين."},"action":{"text":"سلِّمْ لأمر الله ولا تشترطْ على ربّك ما لا يليق."}},{"n":56,"reflection":{"text":"«ثم بعثناكم من بعد موتكم لعلكم تشكرون» — بعثُهم بعد موتهم بالصاعقة، نعمةً أخرى رجاءَ الشكر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الله على تتابع نعمه رغم الذنوب."},"action":{"text":"قابلْ نعم الله المتتابعة بشكرٍ متتابع لا بغفلة."}},{"n":57,"reflection":{"text":"«وظللنا عليكم الغمام وأنزلنا عليكم المن والسلوى كلوا من طيبات ما رزقناكم» — في التِّيه ظلّلهم الغمامُ من الحرّ، وأنزل عليهم المنّ والسلوى؛ وما ظلموا اللهَ بكفرهم بل ظلموا أنفسهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ لطف الله في تدبير الرزق."},"action":{"text":"تأمّلْ رزقًا يأتيك من حيث لا تحتسب واشكرْ مُيسّره."}},{"n":58,"reflection":{"text":"«وإذ قلنا ادخلوا هذه القرية فكلوا منها حيث شئتم رغدا وادخلوا الباب سجدا وقولوا حطة نغفر لكم خطاياكم» — أُمروا بدخول القرية متواضعين خاضعين قائلين «حطّة»: أي حُطّ عنّا خطايانا، فيُغفر لهم ويُزاد المحسنون.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التواضعُ لله عند النعمة، وطلبُ المغفرة."},"action":{"text":"ادخلْ على نعم الله بتواضعٍ واستغفار، لا بأشرٍ وبطر."}},{"n":59,"reflection":{"text":"«فبدل الذين ظلموا قولا غير الذي قيل لهم فأنزلنا على الذين ظلموا رجزا من السماء بما كانوا يفسقون» — بدّل الظالمون القولَ والفعلَ، فأُنزل عليهم عذابٌ من السماء بفسقهم. الدرسُ: خطرُ تحريف أمر الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التزامُ أمر الله كما جاء، وتركُ التبديل."},"action":{"text":"نفِّذْ أمر الشرع كما ورد، ولا تتأوّلْه لهواك."}}]},{"title":"مزيدٌ من النِّعَم والمواثيق، والمسخ","range":[60,66],"theme":"الماءُ من الحجر، ومَلَلُ النعمة، ونقضُ الميثاق","verses":[{"n":60,"reflection":{"text":"«وإذ استسقى موسى لقومه فقلنا اضرب بعصاك الحجر فانفجرت منه اثنتا عشرة عينا قد علم كل أناس مشربهم» — نعمةُ الماء: انفجرت من الحجر اثنتا عشرة عينًا، لكلِّ سبطٍ عينُه، مع النهي عن الإفساد في الأرض.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بقدرة الله على إخراج الرزق من أعسر الأسباب."},"action":{"text":"لا تستبعدْ فرجًا من سببٍ ضعيف؛ فالمُيسّر هو الله."}},{"n":61,"reflection":{"text":"«وإذ قلتم يا موسى لن نصبر على طعام واحد... أتستبدلون الذي هو أدنى بالذي هو خير» — مَلّوا المنّ والسلوى وطلبوا أدنى الطعام؛ فضُربت عليهم الذلّةُ والمسكنة وباؤوا بغضبٍ لكفرهم بآيات الله وقتلهم الأنبياء بغير حقّ وعصيانهم واعتدائهم.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرضا بعطاء الله، وتركُ استبدال الأدنى بالأعلى."},"action":{"text":"ارضَ بما قسم الله لك، ولا تزدرِ نعمةً بين يديك."}},{"n":62,"reflection":{"text":"«إن الذين آمنوا والذين هادوا والنصارى والصابئين من آمن بالله واليوم الآخر وعمل صالحا فلهم أجرهم عند ربهم» — من آمن من الأمم قبل بعثة محمدٍ بنبيّه واليوم الآخر وعمل صالحًا فله أجرُه؛ وبعد بعثة محمدٍ ﷺ لا يُقبل دينٌ إلا الإسلام باتّباعه.","source":"تفسير ابن كثير (والنسخُ بآل عمران ٨٥)","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ النجاة باتّباع الرسول الخاتم."},"action":{"text":"احمدِ الله أن هداك لاتّباع محمدٍ ﷺ، والزمْ سنّته."}},{"n":63,"reflection":{"text":"«وإذ أخذنا ميثاقكم ورفعنا فوقكم الطور خذوا ما آتيناكم بقوة واذكروا ما فيه لعلكم تتقون» — أخذُ الميثاق عليهم ورفعُ الجبل فوقهم؛ ليأخذوا التوراة بجدٍّ وعزم ويعملوا بما فيها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أخذُ أمر الله بقوّةٍ وعزيمة لا بتهاون."},"action":{"text":"خذْ ورد قرآنك وطاعتك بجدٍّ، لا بفتورٍ وكسل."}},{"n":64,"reflection":{"text":"«ثم توليتم من بعد ذلك فلولا فضل الله عليكم ورحمته لكنتم من الخاسرين» — أعرضوا بعد الميثاق؛ ولولا فضلُ الله ورحمتُه بقبول التوبة لكانوا من الهالكين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ أنّ نجاتنا بفضل الله لا بأعمالنا."},"action":{"text":"انسبِ الفضل لله في كلّ نجاةٍ ونعمة، لا لحولك."}},{"n":65,"reflection":{"text":"«ولقد علمتم الذين اعتدوا منكم في السبت فقلنا لهم كونوا قردة خاسئين» — مسخُ الذين تحيّلوا على انتهاك حرمة السبت قردةً صاغرين، جزاءَ الحيلة على محارم الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الحيل على محارم الله."},"action":{"text":"لا تتحيّلْ على حرامٍ بتغيير اسمه أو صورته."}},{"n":66,"reflection":{"text":"«فجعلناها نكالا لما بين يديها وما خلفها وموعظة للمتقين» — جعل اللهُ تلك العقوبةَ عبرةً لمن حضر ومن بعدهم، وموعظةً ينتفع بها المتقون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّعاظُ بعقوبات الأمم السابقة."},"action":{"text":"خذِ العبرة من عقاب العاصين، ولا تسلكْ سبيلهم."}}]},{"title":"قصةُ البقرة التي سُمّيت بها السورة، وقسوةُ القلوب","range":[67,74],"theme":"التشديدُ يجلب التشديد، وإحياءُ الموتى. وبنيةُ القصةِ ظاهرةٌ في النصّ: أُمِروا بـ«بقرة» مطلقةٍ (٦٧)، فما زالوا يسألون حتى ضاق ما وُسِّع لهم — سنّ (٦٨)، فلون (٦٩)، فعملٌ وسلامةٌ من الشِّية (٧١) — ثم «ذبحوها وما كادوا يفعلون». وأجمعت الكتبُ الأربعة (ابن كثير والقرطبي والطبري والسعدي) على المعنى نفسِه عن ابن عباس وأبي العالية وغيرهما: «شددوا فشدد عليهم»","verses":[{"n":67,"reflection":{"text":"«وإذ قال موسى لقومه إن الله يأمركم أن تذبحوا بقرة قالوا أتتخذنا هزوا قال أعوذ بالله أن أكون من الجاهلين» — أمرهم اللهُ بذبح بقرة، فتلقّوه بالاستهزاء واتّهام نبيّهم، فاستعاذ من الجهل بالله وشرعه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ لأمر الله بلا اعتراض ولا استهزاء."},"action":{"text":"امتثلْ أمر الله فور علمِك به، ولا تماطلْ بالأسئلة."}},{"n":68,"reflection":{"text":"«قالوا ادع لنا ربك يبين لنا ما هي قال إنه يقول إنها بقرة لا فارض ولا بكر عوان بين ذلك فافعلوا ما تؤمرون» — أوّلُ سؤالٍ، فأوّلُ قيد (السنّ). قال ابن كثير: «ولهذا لما ضيقوا على أنفسهم ضيق عليهم، ولو أنهم ذبحوا أي بقرة كانت لوقعت الموقع عنهم، كما قال ابن عباس وعبيدة وغير واحد، ولكنهم شددوا فشدد عليهم». وختمَ الأمرَ بـ«فافعلوا ما تؤمرون» — أي كُفّوا عن السؤال وامتثِلوا.","source":"تفسير ابن كثير نصاً (٢:٦٨) — النص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ التنطّع الذي يجلب المشقّة."},"action":{"text":"لا تكثرْ من السؤال المتكلَّف عمّا كُفيته؛ فالتشديد يجرّ التشديد."}},{"n":69,"reflection":{"text":"«قالوا ادع لنا ربك يبين لنا ما لونها قال إنه يقول إنها بقرة صفراء فاقع لونها تسر الناظرين» — مزيدُ تعنّتٍ في السؤال عن لونها، فزيد في التقييد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليُسرُ في الدين ما لم نعسّرْه على أنفسنا."},"action":{"text":"خذْ بالميسور من أمر الله، ولا تعسّرْه بالتنطّع."}},{"n":70,"reflection":{"text":"«قالوا ادع لنا ربك يبين لنا ما هي إن البقر تشابه علينا وإنا إن شاء الله لمهتدون» — سؤالٌ ثالث. وفي آخرها لطيفةٌ نجّتهم: أدبُ الاستثناء. قال الطبري: «ولولا أن القوم استثنوا فقالوا: ﴿وإنا إن شاء الله لمهتدون﴾، لما هدوا إليها أبدا»، وقال السعدي: «ولو لم يقولوا «إن شاء الله» لم يهتدوا أيضا إليها». فكلمةٌ واحدةٌ من الأدب مع الله فتحت لهم بابًا كادوا يُغلقونه بأسئلتهم.","source":"تفسير الطبري والسعدي نصاً (٢:٧٠) — النصوص في تبويب التفاسير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ السريع خيرٌ من التردّد المعنِّت."},"action":{"text":"إذا اتّضح لك أمرُ الله فبادرْ، ولا تُطِلِ التردّد."}},{"n":71,"reflection":{"text":"«قال إنه يقول إنها بقرة لا ذلول تثير الأرض ولا تسقي الحرث مسلمة لا شية فيها قالوا الآن جئت بالحق فذبحوها وما كادوا يفعلون» — القيدُ الرابع، ثم ذبحوها بالكاد. قال السعدي: «قالوا الآن جئت بالحق أي: بالبيان الواضح، وهذا من جهلهم، وإلا فقد جاءهم بالحق أول مرة» — فالحقُّ كان تامًّا من أوّل لحظة، والنقصُ كان فيهم. وقال القرطبي: «ولو امتثلوا الأمر وذبحوا أي بقرة كانت لحصل المقصود، لكنهم شددوا على أنفسهم فشدد الله عليهم».","source":"تفسير السعدي والقرطبي نصاً (٢:٧١) — النصوص في تبويب التفاسير","grade":"ma'thur"},"textual_note":{"title":"الدرسُ الذي سُمّيت السورةُ به — وحذَّرَنا نبيُّنا ﷺ منه بعينه","text":"أُمِروا بأهونِ شيء: «بقرة» — أيُّ بقرة. فما زالوا يسألون حتى صارت بقرةً واحدةً في الأرض لا تكاد تُوجد. والتضييقُ صنعُ أيديهم لا صنعُ الأمر. قال الطبري: «فشددوا على أنفسهم — شدد الله عليهم بكثرة سؤالهم نبيهم واختلافهم عليه»، ثم ساق قولَ نبيِّنا ﷺ لأمّته: «ذروني ما تركتكم، فإنما أهلك من كان قبلكم بكثرة سؤالهم واختلافهم على أنبيائهم. فإذا أمرتكم بشيء فأتوه، وإذا نهيتكم عن شيء فانتهوا عنه ما استطعتم». فالقصةُ ليست تاريخًا لقومٍ مضوا — هي تحذيرٌ لنا نحن، ولذلك سُمّيت السورةُ بها.","grade":"ma'thur","evidence":"الأثرُ متّفقٌ عليه في أربعةٍ من الكتب الستة نصًّا (ابن كثير، القرطبي، الطبري، السعدي) عن ابن عباس وأبي العالية وعبيدة وغيرهم. والحديثُ ساقه الطبريُّ هنا، وهو في الصحيحين."},"israiliyyat_note":{"title":"وما اشتهر من تفاصيلها لا يُعتمد — بشهادة ابن كثير نفسه","text":"يُروى في هذه القصة أنّ البقرة وُجدت عند عجوزٍ لها أيتام، وأنها بيعت بملء جلدها ذهبًا، وغيرُ ذلك. وهذه أخبارٌ إسرائيليّة، قال ابن كثير عنها بنصّه: «مأخوذة من كتب بني إسرائيل وهي مما يجوز نقلها ولكن لا نصدق ولا نكذب فلهذا لا نعتمد عليها إلا ما وافق الحق عندنا، والله أعلم». فالعِبرةُ ثابتةٌ في القرآن، والتفاصيلُ موقوفة — وهذا التفريقُ منهجُ ابنِ كثير قبل أن يكون منهجَنا.","grade":"ma'thur","source":"تفسير ابن كثير نصاً (٢:٦٧-٧٣)"},"names":[],"heart_state":{"text":"بركةُ المسارعة للطاعة، وشؤمُ المماطلة."},"action":{"text":"سارعْ إلى الخير قبل أن يثقُل عليك ويشقّ."}},{"n":72,"reflection":{"text":"«وإذ قتلتم نفسا فادارأتم فيها والله مخرج ما كنتم تكتمون» — قصةُ القتيل الذي تدافعوا في شأنه وكتموا قاتله، والله مُظهِرٌ ما كتموا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ الله يُظهر ما يُكتَم من الحقّ."},"action":{"text":"لا تكتمْ شهادةً أو حقًّا؛ فالله مُخرِجُ ما كتمت."}},{"n":73,"reflection":{"text":"«فقلنا اضربوه ببعضها كذلك يحيي الله الموتى ويريكم آياته لعلكم تعقلون» — أحيا اللهُ القتيلَ بضربه ببعض البقرة فأخبر بقاتله؛ آيةً على البعث ودليلًا يُعقَل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعث الذي أراه الله في الدنيا."},"action":{"text":"قوِّ يقينك بالبعث بتدبّر آيات الإحياء في القرآن والكون."}},{"n":74,"reflection":{"text":"«ثم قست قلوبكم من بعد ذلك فهي كالحجارة أو أشد قسوة وإن من الحجارة لما يتفجر منه الأنهار» — قست قلوبُهم بعد هذه الآيات حتى صارت كالحجارة أو أقسى؛ فإنّ من الحجارة ما يتفجّر منه الماء وما يهبط من خشية الله، وقلوبُهم لا تلين.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من قسوة القلب، وطلبُ لينه بذكر الله."},"action":{"text":"عالجْ قسوة قلبك بالقرآن والذكر وزيارة المقابر."}}]},{"title":"تحريفُ الكتاب، وأمانيُّ أهله، وحقيقةُ الجزاء","range":[75,82],"theme":"خطرُ العلم بلا عمل، وبطلانُ الأماني","verses":[{"n":75,"reflection":{"text":"«أفتطمعون أن يؤمنوا لكم وقد كان فريق منهم يسمعون كلام الله ثم يحرفونه من بعد ما عقلوه وهم يعلمون» — كيف تطمعون في إيمانهم وقد حرّف فريقٌ منهم كلام الله بعد فهمِه عمدًا وعلمًا؟","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من تحريف الحقّ بعد معرفته."},"action":{"text":"احفظِ الحقّ الذي علمتَه من التحريف، واعملْ به."}},{"n":76,"reflection":{"text":"«وإذا لقوا الذين آمنوا قالوا آمنا وإذا خلا بعضهم إلى بعض قالوا أتحدثونهم بما فتح الله عليكم ليحاجوكم به عند ربكم» — نفاقُهم: يُظهرون الإيمان، ويلوم بعضُهم بعضًا على إخبار المسلمين بما في كتبهم من صفة النبيّ ﷺ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصدقُ في السرّ والعلن، وكتمانُ لا شيءٍ من الحقّ."},"action":{"text":"لا تُخفِ حقًّا يلزم إظهارُه لأجل مصلحةٍ عاجلة."}},{"n":77,"reflection":{"text":"«أولا يعلمون أن الله يعلم ما يسرون وما يعلنون» — توبيخٌ: أما يعلمون أنّ الله مطّلعٌ على سرّهم وعلنهم فلا يخفى عليه تحريفُهم؟","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ اطّلاع الله على السرّ والعلن."},"action":{"text":"راقبِ الله في سرّك كما تراقبه في علنك."}},{"n":78,"reflection":{"text":"«ومنهم أميون لا يعلمون الكتاب إلا أماني وإن هم إلا يظنون» — منهم عوامٌّ لا يعرفون من الكتاب إلا تلاوةً بلا فهم أو أمانيَّ كاذبة، يبنون دينهم على الظنّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العلم بالكتاب فهمًا لا مجرّد تلاوة."},"action":{"text":"لا تكتفِ بتلاوة القرآن؛ اطلبْ فهمَ معناه لتعمل به."}},{"n":79,"reflection":{"text":"«فويل للذين يكتبون الكتاب بأيديهم ثم يقولون هذا من عند الله ليشتروا به ثمنا قليلا» — وعيدٌ شديد لمن يكتب الباطل بيده وينسبه إلى الله طمعًا في عرضٍ زائل؛ فلهم الويلُ ممّا كتبوا وكسبوا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من القول على الله بلا علم لأجل الدنيا."},"action":{"text":"لا تنسبْ إلى الدين ما ليس منه لمصلحةٍ أو هوى."}},{"n":80,"reflection":{"text":"«وقالوا لن تمسنا النار إلا أياما معدودة قل أتخذتم عند الله عهدا فلن يخلف الله عهده أم تقولون على الله ما لا تعلمون» — زعموا أنّ النار لن تمسّهم إلا أيامًا؛ فرُدّ عليهم: أعندكم بذلك عهدٌ من الله، أم تقولون عليه بلا علم؟","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الأمانيّ الكاذبة على الله، والعملُ للنجاة."},"action":{"text":"لا تتّكلْ على أمنيّةٍ بلا عمل؛ فالنجاة بالإيمان والطاعة."}},{"n":81,"reflection":{"text":"«بلى من كسب سيئة وأحاطت به خطيئته فأولئك أصحاب النار هم فيها خالدون» — من أحاطت به خطيئتُه حتى استغرقته (وهي الكفر) فهو من أهل النار الخالدين، لا كما زعموا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من إحاطة الذنوب بالقلب."},"action":{"text":"لا تدعِ الذنوب تتراكم حتى تحيط بقلبك؛ تبْ أوّلًا بأوّل."}},{"n":82,"reflection":{"text":"«والذين آمنوا وعملوا الصالحات أولئك أصحاب الجنة هم فيها خالدون» — في مقابل أولئك: أهلُ الإيمان والعمل الصالح أصحابُ الجنة خالدين فيها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في وعد الله لأهل الإيمان والعمل."},"action":{"text":"اجمعْ بين إيمانٍ في القلب وعملٍ بالجوارح؛ فهما مِفتاحُ الجنة."}}]},{"title":"ميثاقٌ جامعٌ منقوض","range":[83,86],"theme":"أوامرُ الميثاق، ونقضُها، وإيثارُ الدنيا","verses":[{"n":83,"reflection":{"text":"«وإذ أخذنا ميثاق بني إسرائيل لا تعبدون إلا الله وبالوالدين إحسانا وذي القربى واليتامى والمساكين وقولوا للناس حسنا وأقيموا الصلاة وآتوا الزكاة ثم توليتم إلا قليلا منكم» — ميثاقٌ جامع: توحيدٌ، وبرُّ الوالدين، وصلةُ القربى، وإحسانٌ لليتامى والمساكين، وحسنُ القول للناس، وإقامةُ الصلاة والزكاة؛ ثم أعرض أكثرُهم.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين حقّ الله وحقوق الخلق، وحسنِ الخلق."},"action":{"text":"أحسنْ اليوم إلى والديك، وقلْ للناس أحسنَ ما تجد."}},{"n":84,"reflection":{"text":"«وإذ أخذنا ميثاقكم لا تسفكون دماءكم ولا تخرجون أنفسكم من دياركم ثم أقررتم وأنتم تشهدون» — أخذ عليهم ميثاقَ حرمة الدماء والديار، فأقرّوا وشهدوا على أنفسهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ حرمة دم المسلم وماله."},"action":{"text":"احفظْ حرمة إخوانك: دماءَهم وأعراضَهم وديارَهم."}},{"n":85,"reflection":{"text":"«ثم أنتم هؤلاء تقتلون أنفسكم وتخرجون فريقا منكم من ديارهم... أفتؤمنون ببعض الكتاب وتكفرون ببعض» — نقضوا الميثاق: يقتلون ويُخرجون بالإثم، ثم يفادون الأسرى؛ فآمنوا ببعض الكتاب وكفروا ببعض، فجزاؤهم الخزيُ في الدنيا وأشدُّ العذاب في الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أخذُ الدين كلِّه، وتركُ التبعيض فيه بالهوى."},"action":{"text":"لا تأخذْ من الدين ما يوافق هواك وتدعْ ما يخالفه."}},{"n":86,"reflection":{"text":"«أولئك الذين اشتروا الحياة الدنيا بالآخرة فلا يخفف عنهم العذاب ولا هم ينصرون» — آثروا الدنيا الفانية على الآخرة الباقية، فلا يُخفَّف عنهم العذاب ولا ناصرَ لهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ الباقية على الفانية."},"action":{"text":"إذا تعارضت دنياك وآخرتك في أمرٍ فقدّمْ آخرتك."}}]},{"title":"تكذيبُ الرسل حسدًا، وأمانيُّ الاصطفاء","range":[87,96],"theme":"الاستكبارُ على الوحي، والحرصُ على الحياة","verses":[{"n":87,"reflection":{"text":"«ولقد آتينا موسى الكتاب وقفينا من بعده بالرسل وآتينا عيسى ابن مريم البينات وأيدناه بروح القدس أفكلما جاءكم رسول بما لا تهوى أنفسكم استكبرتم ففريقا كذبتم وفريقا تقتلون» — تتابعُ الرسل، وعيسى والمعجزات مؤيَّدًا بجبريل؛ وكلّما جاءهم رسولٌ بما يخالف الهوى استكبروا فكذّبوا فريقًا وقتلوا فريقًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ الحقّ وإن خالف الهوى."},"action":{"text":"إذا جاءك حقٌّ يخالف هواك فاقبلْه ولا تستكبرْ."}},{"n":88,"reflection":{"text":"«وقالوا قلوبنا غلف بل لعنهم الله بكفرهم فقليلا ما يؤمنون» — اعتذروا بأنّ قلوبهم في أغطيةٍ لا يصل إليها الحقّ؛ بل طُردوا من رحمة الله بكفرهم، فقليلٌ إيمانُهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ الاعتذار الكاذب عن ردّ الحقّ."},"action":{"text":"لا تعتذرْ عن ترك الحقّ بأعذارٍ تعلم بطلانها."}},{"n":89,"reflection":{"text":"«ولما جاءهم كتاب من عند الله مصدق لما معهم وكانوا من قبل يستفتحون على الذين كفروا فلما جاءهم ما عرفوا كفروا به فلعنة الله على الكافرين» — كانوا يستنصرون بقُرب مبعث النبيّ ﷺ، فلمّا جاءهم وعرفوه حقًّا كفروا به حسدًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الحسد الذي يصدّ عن الحقّ."},"action":{"text":"طهِّرْ قلبك من الحسد؛ فإنّه يعمي عن قبول الحقّ."}},{"n":90,"reflection":{"text":"«بئسما اشتروا به أنفسهم أن يكفروا بما أنزل الله بغيا أن ينزل الله من فضله على من يشاء من عباده فباؤوا بغضب على غضب» — كفروا بغيًا وحسدًا أن ينزّل اللهُ فضلَه على غيرهم، فاستحقّوا غضبًا فوق غضب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرضا بقسمة الله وفضله على من يشاء."},"action":{"text":"افرحْ بفضل الله على غيرك ولا تحسدْه عليه."}},{"n":91,"reflection":{"text":"«وإذا قيل لهم آمنوا بما أنزل الله قالوا نؤمن بما أنزل علينا ويكفرون بما وراءه وهو الحق مصدقا لما معهم قل فلم تقتلون أنبياء الله من قبل إن كنتم مؤمنين» — يقتصرون على ما أُنزل عليهم ويكفرون بغيره وهو الحقّ المصدّق؛ فيُقال: لِمَ قتلتم الأنبياء إن كنتم مؤمنين بكتابكم؟","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بكلّ ما أنزل الله لا ببعضه."},"action":{"text":"آمنْ بجميع ما جاء عن الله، ولا تنتقِ منه ما يوافقك."}},{"n":92,"reflection":{"text":"«ولقد جاءكم موسى بالبينات ثم اتخذتم العجل من بعده وأنتم ظالمون» — جاءهم موسى بالمعجزات الظاهرة ثم عبدوا العجل بعده ظالمين لأنفسهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على التوحيد بعد وضوح البراهين."},"action":{"text":"لا تنقضْ يقينك بعد وضوح الدليل لأجل شبهةٍ أو هوى."}},{"n":93,"reflection":{"text":"«وإذ أخذنا ميثاقكم ورفعنا فوقكم الطور خذوا ما آتيناكم بقوة واسمعوا قالوا سمعنا وعصينا وأشربوا في قلوبهم العجل بكفرهم» — قالوا بلسانهم «سمعنا» وبفعلهم «عصينا»، وأُشرب حبُّ العجل في قلوبهم بكفرهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يوافق العملُ القولَ: سمعنا وأطعنا."},"action":{"text":"اجعلْ شعارك «سمعنا وأطعنا» لا «سمعنا وعصينا»."}},{"n":94,"reflection":{"text":"«قل إن كانت لكم الدار الآخرة عند الله خالصة من دون الناس فتمنوا الموت إن كنتم صادقين» — إن زعمتم أنّ الجنة لكم وحدكم فتمنّوا الموت للقاء ما تزعمون إن كنتم صادقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"صدقُ الدعوى يُختبر بالعمل لا بالقول."},"action":{"text":"اجعلْ لكلّ دعوى إيمانٍ عملًا يصدّقها."}},{"n":95,"reflection":{"text":"«ولن يتمنوه أبدا بما قدمت أيديهم والله عليم بالظالمين» — لن يتمنّوا الموت أبدًا لعلمهم بسوء ما قدّموا، والله عليمٌ بظلمهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العليم"],"heart_state":{"text":"الاستعدادُ للقاء الله بعملٍ يُطمئن لا يُخيف."},"action":{"text":"اعملْ عملًا تحبّ أن تلقى الله عليه اليوم."}},{"n":96,"reflection":{"text":"«ولتجدنهم أحرص الناس على حياة ومن الذين أشركوا يود أحدهم لو يعمر ألف سنة وما هو بمزحزحه من العذاب أن يعمر» — أحرصُ الناس على الحياة ولو حياةَ ذلٍّ؛ يودّ أحدهم لو يعمّر ألف سنة، وما طولُ العمر بمنجيه من العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن تكون رغبتي في الحياة لأجل العمل لا لأجل الدنيا."},"action":{"text":"تمنَّ طول العمر لتزداد طاعةً، لا لتزداد تعلّقًا بالدنيا."}}]},{"title":"عداوةُ الوحي، ونبذُ العهد، وفتنةُ السحر","range":[97,103],"theme":"من عادى جبريل عادى الله، والسحرُ كفر","verses":[{"n":97,"reflection":{"text":"«قل من كان عدوا لجبريل فإنه نزله على قلبك بإذن الله مصدقا لما بين يديه وهدى وبشرى للمؤمنين» — من عادى جبريلَ فقد عادى مَلَكًا نزّل القرآن على قلب النبيّ ﷺ بإذن الله، هدًى وبشرى للمؤمنين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محبّةُ ملائكة الله وأنبيائه، وتعظيمُ الوحي."},"action":{"text":"أحبَّ ما أحبّ الله من ملائكته ورسله ووحيه."}},{"n":98,"reflection":{"text":"«من كان عدوا لله وملائكته ورسله وجبريل وميكال فإن الله عدو للكافرين» — عداوةُ أحدٍ من ملائكة الله ورسله عداوةٌ لله، والله عدوٌّ للكافرين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الولاءُ لله وملائكته ورسله."},"action":{"text":"والِ أولياء الله، وعادِ أعداءه، ولا تُبغضْ ما يحبّه."}},{"n":99,"reflection":{"text":"«ولقد أنزلنا إليك آيات بينات وما يكفر بها إلا الفاسقون» — آياتٌ واضحاتُ الدلالة، لا يجحدها إلا خارجٌ عن طاعة الله بعد قيام الحجّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإذعانُ للآيات البيّنات."},"action":{"text":"إذا وضح لك الدليل فأذعنْ، ولا تلتمسْ لردّه مخرجًا."}},{"n":100,"reflection":{"text":"«أوكلما عاهدوا عهدا نبذه فريق منهم بل أكثرهم لا يؤمنون» — من طبعهم نقضُ العهود كلّما عاهدوا؛ لأنّ أكثرهم لا إيمانَ راسخٌ في قلبه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوفاءُ بالعهد خُلقُ المؤمن."},"action":{"text":"أوفِ بعهودك كلِّها، فنقضُ العهد من علامات ضعف الإيمان."}},{"n":101,"reflection":{"text":"«ولما جاءهم رسول من عند الله مصدق لما معهم نبذ فريق من الذين أوتوا الكتاب كتاب الله وراء ظهورهم كأنهم لا يعلمون» — لمّا جاءهم النبيُّ ﷺ مصدّقًا لكتبهم، نبذ فريقٌ منهم كتاب الله وراء ظهورهم متجاهلين ما يعلمون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ كتاب الله والعملُ به لا نبذُه."},"action":{"text":"لا تجعلْ قرآنك وراء ظهرك بالهجر والغفلة."}},{"n":102,"reflection":{"text":"«واتبعوا ما تتلوا الشياطين على ملك سليمان وما كفر سليمان ولكن الشياطين كفروا يعلمون الناس السحر» — اتّبعوا السحرَ الذي نسبته الشياطينُ إلى ملك سليمان، وسليمانُ بريءٌ منه؛ بل الشياطينُ كفروا بتعليم الناس السحر الذي يُفرَّق به بين المرء وزوجه، ولا يضرّون به إلا بإذن الله؛ ولبئس ما باعوا به أنفسهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التبرّؤُ من السحر وأهله، فهو كفر."},"action":{"text":"اجتنبِ السحر تعلّمًا وعملًا وإتيانًا، فهو من الموبقات."}},{"n":103,"reflection":{"text":"«ولو أنهم آمنوا واتقوا لمثوبة من عند الله خير لو كانوا يعلمون» — لو آمنوا واتّقوا لكان ثوابُ الله خيرًا لهم ممّا آثروه، لو كانوا يعلمون قدرَ ما فاتهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ ثواب الله خيرٌ من كلّ عاجل."},"action":{"text":"وازِنْ بين لذّةٍ عاجلةٍ محرّمة وثوابِ الله الباقي، واخترْ ثوابه."}}]},{"title":"أدبُ الخطاب، والنسخ، وحسدُ أهل الكتاب","range":[104,110],"theme":"حكمةُ التشريع، والعفوُ مع إقامة الطاعة","verses":[{"n":104,"reflection":{"text":"«يا أيها الذين آمنوا لا تقولوا راعنا وقولوا انظرنا واسمعوا» — نهيٌ عن لفظٍ («راعنا») كان اليهودُ يلوون به ألسنتهم إلى معنًى قبيح؛ فأُمر المؤمنون بلفظٍ سالمٍ («انظرنا»)، سدًّا لذريعة الأذى.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تخيّرُ أحسن الألفاظ، وسدُّ ذرائع الشرّ."},"action":{"text":"انتقِ لفظك، ودعْ ما يحتمل معنًى سيّئًا ولو لم تقصده."}},{"n":105,"reflection":{"text":"«ما يود الذين كفروا من أهل الكتاب ولا المشركين أن ينزل عليكم من خير من ربكم والله يختص برحمته من يشاء» — يحسدونكم أن ينزّل اللهُ عليكم خيرًا؛ والله يخصّ برحمته من يشاء، ذو الفضل العظيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الفرحُ بفضل الله، وعدمُ الاكتراث بحسد الحاسدين."},"action":{"text":"لا يصرفنّك حسدُ حاسدٍ عن خيرٍ آتاك الله."}},{"n":106,"reflection":{"text":"«ما ننسخ من آية أو ننسها نأت بخير منها أو مثلها ألم تعلم أن الله على كل شيء قدير» — النسخُ من حكمة الله ورحمته: ما يرفع حكمَ آيةٍ يأتِ بخيرٍ منها أو مثلها؛ فهو القادرُ المدبّر لحكمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكمة الله في تشريعه ونسخه."},"action":{"text":"سلّمْ لأحكام الله، واعلمْ أنّ فيها الحكمةَ وإن خفيت."}},{"n":107,"reflection":{"text":"«ألم تعلم أن الله له ملك السماوات والأرض وما لكم من دون الله من ولي ولا نصير» — له الملكُ المطلق، فله أن يأمر وينهى ويشرّع وينسخ؛ ولا وليَّ لكم سواه ولا نصير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الافتقارُ إلى الله وحده وليًّا وناصرًا."},"action":{"text":"اجعلْ توكّلك على الله وحده، فلا وليَّ سواه."}},{"n":108,"reflection":{"text":"«أم تريدون أن تسألوا رسولكم كما سئل موسى من قبل ومن يتبدل الكفر بالإيمان فقد ضل سواء السبيل» — نهيٌ عن كثرة السؤال تعنّتًا كما فعل قومُ موسى؛ ومن استبدل الكفر بالإيمان فقد ضلّ الطريق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ التعنّت في السؤال، والقناعةُ بما بُيِّن."},"action":{"text":"اقبلِ الحقّ الواضح، ولا تُثقلْه بأسئلة التعنّت."}},{"n":109,"reflection":{"text":"«ود كثير من أهل الكتاب لو يردونكم من بعد إيمانكم كفارا حسدا من عند أنفسهم من بعد ما تبين لهم الحق فاعفوا واصفحوا حتى يأتي الله بأمره» — حسدُهم يودّ ردّكم كفّارًا بعد إيمانكم؛ فقابلوهم بالعفو والصفح حتى يأتي أمرُ الله.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحلمُ والعفو مع الثبات على الحقّ."},"action":{"text":"اعفُ عمّن أساء إليك حسدًا، وامضِ في طاعتك."}},{"n":110,"reflection":{"text":"«وأقيموا الصلاة وآتوا الزكاة وما تقدموا لأنفسكم من خير تجدوه عند الله إن الله بما تعملون بصير» — بعد الأمر بالعفو: الاشتغالُ بالطاعة؛ فأقيموا الصلاة والزكاة، وكلُّ خيرٍ تقدّمونه تجدونه محفوظًا عند الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["البصير"],"heart_state":{"text":"استحضارُ أنّ كلّ خيرٍ مدّخرٌ عند الله."},"action":{"text":"قدِّمْ خيرًا اليوم واحتسبْه عند الله، فهو لا يضيع."}}]},{"title":"دعوى احتكار الهداية، وسعةُ الله","range":[111,121],"theme":"البرهانُ لا الأماني، والوجهةُ لله","verses":[{"n":111,"reflection":{"text":"«وقالوا لن يدخل الجنة إلا من كان هودا أو نصارى تلك أمانيهم قل هاتوا برهانكم إن كنتم صادقين» — زعم كلٌّ أنّ الجنة له وحده؛ وتلك أمانيُّ بلا دليل، فطُولبوا بالبرهان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"بناءُ الدين على البرهان لا على التمنّي."},"action":{"text":"لا تدّعِ نجاةً بلا عمل؛ فالدعوى تحتاج برهانًا."}},{"n":112,"reflection":{"text":"«بلى من أسلم وجهه لله وهو محسن فله أجره عند ربه ولا خوف عليهم ولا هم يحزنون» — الحقُّ: من أخلص وجهه لله (توحيدًا) وأحسن العمل (اتّباعًا) فله أجرُه، آمنًا من الخوف والحزن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ لله والإحسانُ في العمل — شرطا القبول."},"action":{"text":"أخلصْ عملك لله وأتقِنْه على السنّة، فهما مِفتاحُ الأجر."}},{"n":113,"reflection":{"text":"«وقالت اليهود ليست النصارى على شيء وقالت النصارى ليست اليهود على شيء وهم يتلون الكتاب» — يكفّر بعضُهم بعضًا مع تلاوتهم الكتاب؛ والله يحكم بينهم يوم القيامة فيما اختلفوا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتصامُ بالحقّ لا بالعصبية والتناقض."},"action":{"text":"زِنْ مواقفك بالحقّ لا بالهوى والعصبية."}},{"n":114,"reflection":{"text":"«ومن أظلم ممن منع مساجد الله أن يذكر فيها اسمه وسعى في خرابها أولئك ما كان لهم أن يدخلوها إلا خائفين» — لا أظلمَ ممّن منع ذكر الله في مساجده وسعى في تعطيلها؛ لهم في الدنيا خزيٌ وفي الآخرة عذابٌ عظيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ بيوت الله وعمارتُها بالذكر."},"action":{"text":"اعمرْ مساجد الله بصلاتك وذكرك، ولا تُعِنْ على تعطيلها."}},{"n":115,"reflection":{"text":"«ولله المشرق والمغرب فأينما تولوا فثم وجه الله إن الله واسع عليم» — له المشرقُ والمغرب؛ فسعةُ ملكه ورحمته وعلمه تسع كلَّ شيء، والعبدُ يتوجّه حيث أمره الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الواسع","العليم"],"heart_state":{"text":"استحضارُ سعة الله في ملكه ورحمته وعلمه."},"action":{"text":"أينما كنتَ فاذكرْ ربّك، فليس لرحمته جهةٌ تحصرها."}},{"n":116,"reflection":{"text":"«وقالوا اتخذ الله ولدا سبحانه بل له ما في السماوات والأرض كل له قانتون» — تنزيهُ الله عن الولد؛ بل كلُّ ما في السماوات والأرض مملوكٌ له خاضعٌ لأمره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تنزيهُ الله عن الولد والشريك."},"action":{"text":"نزّهْ ربّك عمّا نسبه إليه الجاهلون، وأقرَّ بعبوديّتك له."}},{"n":117,"reflection":{"text":"«بديع السماوات والأرض وإذا قضى أمرا فإنما يقول له كن فيكون» — مُبدعُهما على غير مثالٍ سبق؛ وإذا أراد شيئًا قال له «كن» فيكون بلا ممانعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["البديع"],"heart_state":{"text":"اليقينُ بنفوذ قدرة الله في كلّ شيء."},"action":{"text":"إذا استعصى عليك أمرٌ فاسألِ الذي يقول للشيء كن فيكون."}},{"n":118,"reflection":{"text":"«وقال الذين لا يعلمون لولا يكلمنا الله أو تأتينا آية كذلك قال الذين من قبلهم مثل قولهم تشابهت قلوبهم» — تعنّتُ الجهّال بطلب أن يكلّمهم الله أو تأتيهم آيةٌ مقترحة؛ تشابهت قلوبُ المعاندين في كلّ زمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاكتفاءُ بالآيات القائمة، وتركُ الاقتراح على الله."},"action":{"text":"لا تعلّقْ إيمانك بآيةٍ تقترحها؛ فالبيّناتُ قائمة."}},{"n":119,"reflection":{"text":"«إنا أرسلناك بالحق بشيرا ونذيرا ولا تسأل عن أصحاب الجحيم» — أُرسل النبيُّ ﷺ بالحقّ مبشّرًا بالجنة ومنذرًا بالنار؛ وليس عليه هدايةُ من أبى، ولا يُسأل عن أهل الجحيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ البلاغ، وتركُ الحرص على ما ليس إليك."},"action":{"text":"بلّغِ الخير، ولا تحملْ همّ هدايةِ القلوب فذاك إلى الله."}},{"n":120,"reflection":{"text":"«ولن ترضى عنك اليهود ولا النصارى حتى تتبع ملتهم قل إن هدى الله هو الهدى ولئن اتبعت أهواءهم بعد الذي جاءك من العلم ما لك من الله من ولي ولا نصير» — لن يرضوا حتى تتّبع ملّتهم؛ وهدى الله هو الهدى وحده، واتّباعُ أهوائهم بعد العلم خذلانٌ ووعيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ رضا الله لا رضا الناس بمخالفة الحقّ."},"action":{"text":"لا تطلبْ رضا أحدٍ بمعصية الله؛ فرضا الله أولى."}},{"n":121,"reflection":{"text":"«الذين آتيناهم الكتاب يتلونه حق تلاوته أولئك يؤمنون به ومن يكفر به فأولئك هم الخاسرون» — من يتلو الكتاب حقّ تلاوته — يتّبع أمره ويجتنب نهيه — يؤمن بالنبيّ ﷺ؛ ومن كفر فهو الخاسر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تلاوةُ القرآن حقَّ تلاوته: اتّباعًا لا مجرّد لفظ."},"action":{"text":"اتلُ القرآن متّبعًا: تُحلّ حلاله وتحرّم حرامه وتعمل بمحكمه."}}]},{"title":"ملّةُ إبراهيم: البناءُ والدعاءُ والاصطفاء","range":[122,134],"theme":"إمامةُ إبراهيم، ورفعُ قواعد البيت، والوصيّةُ بالتوحيد","verses":[{"n":122,"reflection":{"text":"«يا بني إسرائيل اذكروا نعمتي التي أنعمت عليكم وأني فضلتكم على العالمين» — تكرارُ التذكير بالنعمة والتفضيل، تمهيدًا للانتقال إلى أبيهم إبراهيم وملّته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ النعمة يستلزم اتّباعَ الحقّ."},"action":{"text":"اجعلْ شكرك للنعمة طاعةً لمُسديها."}},{"n":123,"reflection":{"text":"«واتقوا يوما لا تجزي نفس عن نفس شيئا ولا يقبل منها عدل ولا تنفعها شفاعة ولا هم ينصرون» — تحذيرٌ مؤكَّد من يومٍ لا فداءَ فيه ولا شفاعةَ إلا بإذنه ولا نصير.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليوم الحساب بالعمل."},"action":{"text":"قدّمْ لآخرتك ما يجزي عنك يوم لا يجزي أحدٌ عن أحد."}},{"n":124,"reflection":{"text":"«وإذ ابتلى إبراهيم ربه بكلمات فأتمهن قال إني جاعلك للناس إماما قال ومن ذريتي قال لا ينال عهدي الظالمين» — ابتلى اللهُ إبراهيمَ بأوامرَ فأتمّها، فجعله إمامًا للناس؛ وسأل الإمامةَ لذرّيته، فبيّن أنّ عهد الإمامة لا يناله ظالم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إتمامُ ما أُمرتَ به يورث الإمامة في الخير."},"action":{"text":"أتمِمْ طاعتك ولا تتركْها ناقصة؛ فالإمامةُ بالإتمام."}},{"n":125,"reflection":{"text":"«وإذ جعلنا البيت مثابة للناس وأمنا واتخذوا من مقام إبراهيم مصلى وعهدنا إلى إبراهيم وإسماعيل أن طهرا بيتي للطائفين والعاكفين والركع السجود» — جعل اللهُ البيتَ مرجعًا للناس وأمنًا، وأمرَ إبراهيم وإسماعيل بتطهيره للعابدين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ بيت الله وشعائره."},"action":{"text":"طهِّرْ مصلّاك وقلبك للعبادة كما طُهِّر بيت الله."}},{"n":126,"reflection":{"text":"«وإذ قال إبراهيم رب اجعل هذا بلدا آمنا وارزق أهله من الثمرات من آمن منهم بالله واليوم الآخر» — دعا إبراهيمُ لمكة بالأمن والرزق لأهلها المؤمنين؛ والكافرُ يُمتَّع قليلًا ثم يُضطرّ إلى عذاب النار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعاءُ بالأمن والرزق مع تقييده بالإيمان."},"action":{"text":"ادعُ الله بأمن بلدك ورزق أهله، واسألْه الثبات على الإيمان."}},{"n":127,"reflection":{"text":"«وإذ يرفع إبراهيم القواعد من البيت وإسماعيل ربنا تقبل منا إنك أنت السميع العليم» — رفعا قواعد الكعبة يبنيانها، داعِيَين بقبول العمل؛ فمع العمل الصالح يُطلب القبول.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"الجمعُ بين العمل الصالح وطلبِ قبوله."},"action":{"text":"إذا عملتَ صالحًا فاسألِ الله قبوله، ولا تُعجَبْ به."}},{"n":128,"reflection":{"text":"«ربنا واجعلنا مسلمين لك ومن ذريتنا أمة مسلمة لك وأرنا مناسكنا وتب علينا إنك أنت التواب الرحيم» — دعاءٌ بالإسلام لهما ولذرّيتهما، وتعليمِ المناسك، وقبولِ التوبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["التواب","الرحيم"],"heart_state":{"text":"الحرصُ على صلاح الذرّية بعد النفس."},"action":{"text":"ادعُ الله أن يجعلك وذرّيتك من المسلمين المخلصين."}},{"n":129,"reflection":{"text":"«ربنا وابعث فيهم رسولا منهم يتلو عليهم آياتك ويعلمهم الكتاب والحكمة ويزكيهم إنك أنت العزيز الحكيم» — دعا إبراهيمُ ببعثة النبيّ ﷺ من ذرّيته؛ فكان محمدٌ ﷺ إجابةَ دعوة إبراهيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العزيز","الحكيم"],"heart_state":{"text":"شكرُ نعمة بعثة النبيّ ﷺ ثمرةِ دعوة إبراهيم."},"action":{"text":"اشكرِ الله على نعمة الرسالة، وتعلّمِ الكتاب والحكمة وتزكَّ."}},{"n":130,"reflection":{"text":"«ومن يرغب عن ملة إبراهيم إلا من سفه نفسه ولقد اصطفيناه في الدنيا وإنه في الآخرة لمن الصالحين» — لا يزهد في ملّة إبراهيم (التوحيد) إلا من سفِه نفسه وأهانها؛ وقد اصطفاه اللهُ في الدنيا وهو من الصالحين في الآخرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ ملّة التوحيد، والرغبةُ فيها."},"action":{"text":"تمسّكْ بملّة إبراهيم: إخلاصُ الدين لله وحده."}},{"n":131,"reflection":{"text":"«إذ قال له ربه أسلم قال أسلمت لرب العالمين» — بادر إبراهيمُ بالاستسلام لله حين أُمر، بلا تردّد: «أسلمتُ لربّ العالمين».","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["رب العالمين"],"heart_state":{"text":"المبادرةُ للاستسلام لله عند أمره."},"action":{"text":"استسلمْ لأمر الله فورًا كما فعل إبراهيم، بلا مماطلة."}},{"n":132,"reflection":{"text":"«ووصى بها إبراهيم بنيه ويعقوب يا بني إن الله اصطفى لكم الدين فلا تموتن إلا وأنتم مسلمون» — أوصى إبراهيمُ ويعقوبُ بنيهما بالثبات على الإسلام حتى الممات؛ فأعظمُ ما يورَّث الدين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العنايةُ بأن يُختم للأبناء بالإسلام."},"action":{"text":"أوصِ أهلك ومن تحبّ بالثبات على الدين حتى الموت."}},{"n":133,"reflection":{"text":"«أم كنتم شهداء إذ حضر يعقوب الموت إذ قال لبنيه ما تعبدون من بعدي قالوا نعبد إلهك وإله آبائك إبراهيم وإسماعيل وإسحاق إلها واحدا ونحن له مسلمون» — استوثق يعقوبُ من بنيه عند الموت على التوحيد، فأقرّوا بعبادة الإله الواحد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يكون همُّ المسلم عند الموت توحيدَ من بعده."},"action":{"text":"اجعلْ آخر ما تُوصي به أهلك: توحيد الله ولزوم دينه."}},{"n":134,"reflection":{"text":"«تلك أمة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسألون عما كانوا يعملون» — كلُّ نفسٍ مرهونةٌ بعملها؛ لا ينفعكم انتسابٌ إلى صالحٍ بلا عمل، ولا تُسألون عن عمل غيركم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاتّكالُ على العمل لا على الأنساب."},"action":{"text":"لا تتّكلْ على شرف نسبٍ أو انتماء؛ قدّمْ عملك أنت."}}]},{"title":"الحنيفيّةُ السمحة لا يهوديّةٌ ولا نصرانيّة","range":[135,141],"theme":"دينُ إبراهيم، والإيمانُ بالرسل بلا تفريق","verses":[{"n":135,"reflection":{"text":"«وقالوا كونوا هودا أو نصارى تهتدوا قل بل ملة إبراهيم حنيفا وما كان من المشركين» — دعوا إلى اليهودية أو النصرانية؛ فالجوابُ: بل الهدى في ملّة إبراهيم الحنيف المائل عن الشرك إلى التوحيد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتزازُ بملّة التوحيد الحنيفية."},"action":{"text":"اثبتْ على التوحيد الخالص، ولا تنجرفْ وراء كلِّ دعوة."}},{"n":136,"reflection":{"text":"«قولوا آمنا بالله وما أنزل إلينا وما أنزل إلى إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط وما أوتي موسى وعيسى وما أوتي النبيون من ربهم لا نفرق بين أحد منهم ونحن له مسلمون» — الإيمانُ بالله وبكلّ ما أنزله على أنبيائه، بلا تفريقٍ بينهم، مع الاستسلام لله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بجميع الأنبياء والكتب بلا تفريق."},"action":{"text":"آمنْ بكلّ أنبياء الله، وأحبَّهم جميعًا، ولا تفرّقْ بينهم."}},{"n":137,"reflection":{"text":"«فإن آمنوا بمثل ما آمنتم به فقد اهتدوا وإن تولوا فإنما هم في شقاق فسيكفيكهم الله وهو السميع العليم» — ميزانُ الهداية: أن يؤمنوا كإيمانكم الجامع؛ فإن تولّوا فهم في خلافٍ ومعاندة، والله يكفيك شرّهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"الطمأنينةُ إلى كفاية الله لعبده."},"action":{"text":"إذا آذاك المعاندون فاعتمدْ على كفاية الله، وامضِ في حقّك."}},{"n":138,"reflection":{"text":"«صبغة الله ومن أحسن من الله صبغة ونحن له عابدون» — فطرةُ الله ودينُه الذي فطر عليه الخلق أحسنُ صبغةٍ تصطبغ بها النفوس، ونحن له وحده عابدون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتزازُ بدين الفطرة، وإفرادُ الله بالعبادة."},"action":{"text":"الزمْ دين الفطرة، واجعلْ عبادتك كلَّها لله."}},{"n":139,"reflection":{"text":"«قل أتحاجوننا في الله وهو ربنا وربكم ولنا أعمالنا ولكم أعمالكم ونحن له مخلصون» — لا معنى للمحاجّة في الله وهو ربُّ الجميع؛ لكلٍّ عملُه، ونحن نخلص له العبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ لله، وتركُ الجدال العقيم."},"action":{"text":"أخلصْ عملك لله، ودعِ الجدال الذي لا يثمر هدى."}},{"n":140,"reflection":{"text":"«أم تقولون إن إبراهيم وإسماعيل وإسحاق ويعقوب والأسباط كانوا هودا أو نصارى قل أأنتم أعلم أم الله ومن أظلم ممن كتم شهادة عنده من الله» — إنكارُ دعوى تهوّد الأنبياء أو تنصّرهم — وهم قبل اليهودية والنصرانية؛ ولا أظلمَ ممّن كتم شهادةً عنده من الله (صفة النبيّ ﷺ).","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من كتمان الشهادة والحقّ."},"action":{"text":"أدِّ الشهادة بالحقّ، ولا تكتمْ ما يلزمك بيانُه."}},{"n":141,"reflection":{"text":"«تلك أمة قد خلت لها ما كسبت ولكم ما كسبتم ولا تسألون عما كانوا يعملون» — خاتمةٌ مؤكِّدة: لكلٍّ كسبُه، فلا ينفعُ الفخرُ بالسلف مع تركِ العمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانشغالُ بالعمل لا بالانتساب."},"action":{"text":"اشغلْ نفسك بتقديم العمل الصالح، لا بذكر أمجاد الماضين."}}]},{"title":"تحويلُ القبلة: ابتلاءٌ وحكمة","range":[142,152],"theme":"الأمّةُ الوسط، ونعمةُ الرسول، والذكرُ والشكر","verses":[{"n":142,"reflection":{"text":"«سيقول السفهاء من الناس ما ولاهم عن قبلتهم التي كانوا عليها قل لله المشرق والمغرب يهدي من يشاء إلى صراط مستقيم» — اعتراضُ ضعفاء العقول على تحويل القبلة؛ والجوابُ: لله الجهاتُ كلُّها، يهدي من يشاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لحكم الله في وجهة العبادة."},"action":{"text":"استقبلْ حكم الله بالقبول، ولا تلتفتْ لاعتراض السفهاء."}},{"n":143,"reflection":{"text":"«وكذلك جعلناكم أمة وسطا لتكونوا شهداء على الناس ويكون الرسول عليكم شهيدا وما جعلنا القبلة التي كنت عليها إلا لنعلم من يتبع الرسول ممن ينقلب على عقبيه... وما كان الله ليضيع إيمانكم» — جعلكم أمّةً عدلًا خيارًا، والقبلةُ الأولى ابتلاءٌ ليُعلم المتّبعُ من المرتدّ؛ ولن يضيّع اللهُ صلاتكم السابقة.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":["الرؤوف","الرحيم"],"heart_state":{"text":"الطمأنينةُ إلى أنّ الله لا يضيّع عمل المؤمن."},"action":{"text":"اثبتْ عند الابتلاء، فبه يتميّز الصادقُ من المتقلّب."}},{"n":144,"sabab":{"text":"كان النبيُّ ﷺ يحبّ أن يُوجَّه إلى الكعبة، فجعل يُقلّب وجهه في السماء يرجو نزول الوحي بذلك، فنزلت.","source":"متّفق عليه (البخاري ومسلم عن البراء بن عازب)","grade":"ma'thur"},"reflection":{"text":"«قد نرى تقلب وجهك في السماء فلنولينك قبلة ترضاها فول وجهك شطر المسجد الحرام» — أجاب اللهُ رغبةَ نبيّه فحوّل القبلة إلى الكعبة التي يحبّها؛ وأهلُ الكتاب يعلمون أنّه الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محبّةُ ما يحبّه الله ورسوله من الشعائر."},"action":{"text":"استقبلِ القبلة في صلاتك مستحضرًا أنّها اختيارُ الله لك."}},{"n":145,"reflection":{"text":"«ولئن أتيت الذين أوتوا الكتاب بكل آية ما تبعوا قبلتك وما أنت بتابع قبلتهم وما بعضهم بتابع قبلة بعض» — عنادُهم لا يزول ولو أتيتهم بكلّ آية؛ فلا تتّبعْ أهواءهم بعد العلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحقّ، وعدمُ مجاراة الأهواء."},"action":{"text":"لا تجارِ من عاند الحقّ طمعًا في رضاه؛ فالثباتُ أولى."}},{"n":146,"reflection":{"text":"«الذين آتيناهم الكتاب يعرفونه كما يعرفون أبناءهم وإن فريقا منهم ليكتمون الحق وهم يعلمون» — يعرفون صدقَ النبيّ ﷺ معرفةً يقينيّة كمعرفتهم أبناءهم، لكنّ فريقًا يكتمون الحقّ عن علم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من كتمان حقٍّ عُرف يقينًا."},"action":{"text":"أظهرِ الحقّ الذي تيقّنته، ولا تكتمْه لهوى أو مصلحة."}},{"n":147,"reflection":{"text":"«الحق من ربك فلا تكونن من الممترين» — الحقُّ الذي معك من ربّك، فلا يدخلنّك شكٌّ ولا امتراء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ الجازم بالحقّ، وطردُ الشكّ."},"action":{"text":"قوِّ يقينك بدينك، ولا تدعِ الشبهاتِ تزلزله."}},{"n":148,"reflection":{"text":"«ولكل وجهة هو موليها فاستبقوا الخيرات أينما تكونوا يأت بكم الله جميعا إن الله على كل شيء قدير» — لكلّ أمّةٍ قبلةٌ يتوجّه إليها؛ والمقصودُ الأعظمُ المسابقةُ إلى الخيرات، فالله يجمع الجميع للجزاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المسارعةُ إلى الخيرات ومنافسةُ أهلها."},"action":{"text":"سابقْ إلى خيرٍ اليوم قبل فواته، ولا تسوّفْ."}},{"n":149,"reflection":{"text":"«ومن حيث خرجت فول وجهك شطر المسجد الحرام وإنه للحق من ربك» — تأكيدُ استقبال الكعبة في كلّ حال؛ فإنّه الحقُّ من الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الالتزامُ بأمر الله في كلّ حالٍ ومكان."},"action":{"text":"التزمْ شعائر الله حيثما كنت، سفرًا وحضرًا."}},{"n":150,"reflection":{"text":"«ومن حيث خرجت فول وجهك شطر المسجد الحرام... لئلا يكون للناس عليكم حجة» — كرّر الأمرَ لحكمةٍ: قطعِ حجّة المخالفين، وإتمامِ النعمة، والهداية؛ فاذكروه ولا تخشوا إلا إياه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"خشيةُ الله وحده، ورجاءُ إتمام نعمته."},"action":{"text":"لا تخشَ في الحقّ لومة لائم، واخشَ الله وحده."}},{"n":151,"reflection":{"text":"«كما أرسلنا فيكم رسولا منكم يتلو عليكم آياتنا ويزكيكم ويعلمكم الكتاب والحكمة ويعلمكم ما لم تكونوا تعلمون» — تعدادُ نعمة الرسول: يتلو الآيات، ويزكّي النفوس، ويعلّم الكتاب والحكمة وما جهلتم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمة الرسول المعلِّم المزكِّي."},"action":{"text":"تعلّمْ من هدي النبيّ ﷺ وزكِّ نفسك باتّباعه."}},{"n":152,"reflection":{"text":"«فاذكروني أذكركم واشكروا لي ولا تكفرون» — وعدٌ عظيم: اذكروا اللهَ يذكركم، واشكروه على نعمه ولا تجحدوها بالمعصية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ ذكر الله وشكرِه رجاءَ أن يذكرنا."},"action":{"text":"أكثِرْ من ذكر الله اليوم؛ فمن ذكره ذكره الله في ملأٍ خير."}}]},{"title":"الاستعانةُ بالصبر، والابتلاء، والشعائر","range":[153,162],"theme":"الشهداءُ أحياء، والاسترجاعُ، وكتمانُ الحقّ","verses":[{"n":153,"reflection":{"text":"«يا أيها الذين آمنوا استعينوا بالصبر والصلاة إن الله مع الصابرين» — عند الشدائد يُستعان بالصبر والصلاة؛ ومعيّةُ الله الخاصّةُ للصابرين نصرًا وتأييدًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ العون بالصبر والصلاة، ورجاءُ معيّة الله."},"action":{"text":"إذا نزل بك همٌّ فاصبرْ وصلِّ، واستحضرْ أنّ الله مع الصابرين."}},{"n":154,"reflection":{"text":"«ولا تقولوا لمن يقتل في سبيل الله أموات بل أحياء ولكن لا تشعرون» — الشهداءُ أحياءٌ عند ربّهم حياةً برزخيّة لا نُدركها؛ فلا تُنزلوهم منزلة الأموات المعدومين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ منزلة الشهادة في سبيل الله."},"action":{"text":"اسألِ الله الشهادة بصدق، وأحبَّ الشهداء."}},{"n":155,"reflection":{"text":"«ولنبلونكم بشيء من الخوف والجوع ونقص من الأموال والأنفس والثمرات وبشر الصابرين» — الابتلاءُ سنّةٌ ماضية؛ يُبتلى المؤمنُ في نفسه وماله؛ والبشرى للصابرين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توطينُ النفس على الابتلاء، والصبرُ عليه."},"action":{"text":"استقبلِ البلاء بالصبر واحتساب الأجر، فهو للمؤمن خير."}},{"n":156,"reflection":{"text":"«الذين إذا أصابتهم مصيبة قالوا إنا لله وإنا إليه راجعون» — صفةُ الصابرين: إذا نزلت بهم مصيبةٌ استرجعوا، مُقرّين بأنّهم ملكٌ لله راجعون إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بملك الله لنا ورجوعنا إليه عند المصيبة."},"action":{"text":"عند كلّ مصيبةٍ قلْ من قلبك: إنّا لله وإنّا إليه راجعون."}},{"n":157,"reflection":{"text":"«أولئك عليهم صلوات من ربهم ورحمة وأولئك هم المهتدون» — جزاءُ الصابرين المسترجعين: ثناءٌ من الله ومغفرةٌ ورحمة، وهم المهتدون إلى الحقّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في صلوات الله ورحمته للصابرين."},"action":{"text":"اصبرْ محتسبًا، فجزاءُ الصبر رحمةٌ وهدى من الله."}},{"n":158,"sabab":{"text":"كان الأنصارُ قبل إسلامهم يُهِلّون لصنمين على الصفا والمروة، فلمّا أسلموا تحرّجوا من الطواف بينهما، فنزلت تبيّن أنّهما من شعائر الله.","source":"متّفق عليه (البخاري ومسلم عن عائشة)","grade":"ma'thur"},"reflection":{"text":"«إن الصفا والمروة من شعائر الله فمن حج البيت أو اعتمر فلا جناح عليه أن يطوف بهما ومن تطوع خيرا فإن الله شاكر عليم» — السعيُ بين الصفا والمروة من شعائر الله في الحجّ والعمرة؛ ومن زاد خيرًا فالله يشكره ويعلمه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الشاكر","العليم"],"heart_state":{"text":"تعظيمُ شعائر الله وأداؤها بخشوع."},"action":{"text":"عظِّمْ شعائر الله، وتطوّعْ بالخير فالله شاكرٌ لا يضيع."}},{"n":159,"reflection":{"text":"«إن الذين يكتمون ما أنزلنا من البينات والهدى من بعد ما بيناه للناس في الكتاب أولئك يلعنهم الله ويلعنهم اللاعنون» — وعيدٌ شديد لمن يكتم الحقّ بعد بيانه: طردٌ من رحمة الله ودعاءٌ عليه من كلّ داعٍ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على بيان الحقّ لا كتمانه."},"action":{"text":"بيِّنِ العلم النافع للناس، ولا تكتمْ ما يُنتفع به."}},{"n":160,"reflection":{"text":"«إلا الذين تابوا وأصلحوا وبينوا فأولئك أتوب عليهم وأنا التواب الرحيم» — استثناءُ من كتم ثم تاب وأصلح عملَه وبيّن ما كتم؛ فيتوب الله عليه، فهو التواب الرحيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["التواب","الرحيم"],"heart_state":{"text":"الرجاءُ في قبول التوبة مع الإصلاح والبيان."},"action":{"text":"تبْ من كلِّ تقصير، وأصلحْ ما أفسدت، وبيِّنْ ما كتمت."}},{"n":161,"reflection":{"text":"«إن الذين كفروا وماتوا وهم كفار أولئك عليهم لعنة الله والملائكة والناس أجمعين» — من مات على الكفر استحقّ طردَ الله والملائكة والناس من رحمته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من سوء الخاتمة، وسؤالُ الثبات."},"action":{"text":"اسألِ الله حسن الخاتمة، والثباتَ على الإيمان حتى الموت."}},{"n":162,"reflection":{"text":"«خالدين فيها لا يخفف عنهم العذاب ولا هم ينظرون» — خلودٌ في اللعنة والعذاب، لا يُخفَّف عنهم ولا يُمهَلون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعظامُ عاقبة الكفر، وشكرُ نعمة الإيمان."},"action":{"text":"احمدِ الله على الإيمان، واحذرْ ما يُخرجك منه."}}]},{"title":"دلائلُ التوحيد، والولاءُ والبراء","range":[163,171],"theme":"الإلهُ الواحد، وآياتُ الكون، وحبُّ الله","verses":[{"n":163,"reflection":{"text":"«وإلهكم إله واحد لا إله إلا هو الرحمن الرحيم» — إلهُكم واحدٌ لا شريك له، المستحقُّ وحده للعبادة، الرحمنُ الرحيم الواسعُ الرحمة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرحمن","الرحيم"],"heart_state":{"text":"إفرادُ الله بالعبادة والمحبّة والرجاء."},"action":{"text":"جدّدْ توحيدك: لا معبودَ بحقٍّ إلا الله وحده."}},{"n":164,"reflection":{"text":"«إن في خلق السماوات والأرض واختلاف الليل والنهار والفلك التي تجري في البحر... وبث فيها من كل دابة وتصريف الرياح والسحاب المسخر بين السماء والأرض لآيات لقوم يعقلون» — تعدادُ آيات الكون البديعة الدالّة على وحدانية خالقها لمن يعقل.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التفكّرُ في آيات الكون ليثمر توحيدَ الخالق."},"action":{"text":"تأمّلْ آيةً من آيات الله في السماء أو الأرض، وتدبّرْ عظمة خالقها."}},{"n":165,"reflection":{"text":"«ومن الناس من يتخذ من دون الله أندادا يحبونهم كحب الله والذين آمنوا أشد حبا لله» — من المشركين من يحبّ آلهته كحبّ الله؛ والمؤمنون أشدُّ حبًّا لله لأنّهم أخلصوا حبَّهم له. ولو يرى الظالمون العذاب لعلموا أنّ القوّة لله جميعًا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يكون الله أحبَّ إلى القلب من كلّ شيء."},"action":{"text":"قدِّمْ محبّة الله على كلّ محبوب، ولا تصرفْ للمخلوق ما هو لله."}},{"n":166,"reflection":{"text":"«إذ تبرأ الذين اتبعوا من الذين اتبعوا ورأوا العذاب وتقطعت بهم الأسباب» — يوم القيامة يتبرّأ المتبوعون في الباطل من أتباعهم عند رؤية العذاب، وتنقطع بينهم كلُّ صلةٍ ووسيلة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من موالاة أهل الباطل الذين يتبرّؤون غدًا."},"action":{"text":"اجعلْ ولاءك لله وأوليائه، لا لمن يتبرّأ منك يوم القيامة."}},{"n":167,"reflection":{"text":"«وقال الذين اتبعوا لو أن لنا كرة فنتبرأ منهم كما تبرءوا منا كذلك يريهم الله أعمالهم حسرات عليهم وما هم بخارجين من النار» — يتمنّى الأتباعُ رجعةً ليتبرّؤوا؛ فيُريهم اللهُ أعمالهم حسراتٍ، ولا خروجَ لهم من النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ الدنيا قبل أن تصير الأعمالُ حسرات."},"action":{"text":"أصلحْ عملك اليوم؛ فلا كرّةَ بعد الموت لتصحيحه."}},{"n":168,"reflection":{"text":"«يا أيها الناس كلوا مما في الأرض حلالا طيبا ولا تتبعوا خطوات الشيطان إنه لكم عدو مبين» — إباحةٌ عامّة للطيّبات الحلال، مع النهي عن اتّباع خطوات الشيطان الذي يزيّن الحرام.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على الحلال الطيّب، ومجانبةُ وساوس الشيطان."},"action":{"text":"تحرَّ الحلال في مطعمك، ولا تخطُ خطوةً في طريق الشيطان."}},{"n":169,"reflection":{"text":"«إنما يأمركم بالسوء والفحشاء وأن تقولوا على الله ما لا تعلمون» — الشيطانُ لا يأمر إلا بالسوء والفواحش والقول على الله بغير علم؛ فهو عدوٌّ لا يريد لك خيرًا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من القول على الله بلا علم."},"action":{"text":"لا تقلْ في دين الله برأيك؛ قفْ عند العلم والدليل."}},{"n":170,"reflection":{"text":"«وإذا قيل لهم اتبعوا ما أنزل الله قالوا بل نتبع ما ألفينا عليه آباءنا أولو كان آباؤهم لا يعقلون شيئا ولا يهتدون» — ذمُّ التقليد الأعمى للآباء في الباطل؛ أفيتّبعونهم ولو كانوا لا يعقلون ولا يهتدون؟","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اتّباعُ الدليل لا العادة والتقليد الأعمى."},"action":{"text":"زِنْ عادات آبائك بالوحي؛ فاقبلْ موافقَه ودعْ مخالفه."}},{"n":171,"reflection":{"text":"«ومثل الذين كفروا كمثل الذي ينعق بما لا يسمع إلا دعاء ونداء صم بكم عمي فهم لا يعقلون» — مثلُ الكافرين في عدم انتفاعهم بالدعوة كالبهيمة تسمع الصوتَ ولا تفقه المعنى؛ صمٌّ بكمٌ عميٌ لا يعقلون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ فقه المعنى لا مجرّد سماع اللفظ."},"action":{"text":"أنصتْ للقرآن بقلبٍ يعي، لا بأذنٍ فقط."}}]},{"title":"الطيّباتُ والمحرّمات، وكتمانُ الحقّ","range":[172,176],"theme":"الأكلُ الحلال والشكر، ورخصةُ الاضطرار","verses":[{"n":172,"reflection":{"text":"«يا أيها الذين آمنوا كلوا من طيبات ما رزقناكم واشكروا لله إن كنتم إياه تعبدون» — خطابٌ خاصٌّ للمؤمنين: كلوا من طيّبات الرزق واشكروا الله؛ فالشكرُ من تمام العبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمة الطعام، ونسبتُها إلى الله."},"action":{"text":"احمدِ الله على طعامك، واجعلْه عونًا على طاعته."}},{"n":173,"reflection":{"text":"«إنما حرم عليكم الميتة والدم ولحم الخنزير وما أهل به لغير الله فمن اضطر غير باغ ولا عاد فلا إثم عليه إن الله غفور رحيم» — حصرُ المحرّمات من الطعام في هذه الأصول؛ ورخصةُ الاضطرار لمن لم يبغِ ولم يتجاوز؛ فالله غفورٌ رحيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"الشكرُ لسعة الحلال ويُسر الشريعة."},"action":{"text":"اجتنبِ المحرّم من الطعام، واعلمْ أنّ الأصل في الطيّبات الحلّ."}},{"n":174,"reflection":{"text":"«إن الذين يكتمون ما أنزل الله من الكتاب ويشترون به ثمنا قليلا أولئك ما يأكلون في بطونهم إلا النار ولا يكلمهم الله يوم القيامة ولا يزكيهم ولهم عذاب أليم» — من كتم الكتاب لأجل الدنيا فإنّما يملأ بطنه نارًا؛ ويُحرم كلامَ الله وتزكيتَه يوم القيامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من بيع الدين بعرض الدنيا."},"action":{"text":"لا تبعْ حقًّا أو علمًا بثمنٍ من الدنيا، فعاقبتُه النار."}},{"n":175,"reflection":{"text":"«أولئك الذين اشتروا الضلالة بالهدى والعذاب بالمغفرة فما أصبرهم على النار» — استبدلوا الضلالة بالهدى والعذاب بالمغفرة؛ فما أجرأهم على أسباب النار وأصبرهم على ما لا يُصبَر عليه!","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من الجرأة على أسباب النار."},"action":{"text":"احذرْ كلَّ عملٍ يورد النار، ولا تجترئْ عليه."}},{"n":176,"reflection":{"text":"«ذلك بأن الله نزل الكتاب بالحق وإن الذين اختلفوا في الكتاب لفي شقاق بعيد» — ذلك العذابُ بسبب إعراضهم عن الكتاب المنزَّل بالحقّ؛ والمختلفون فيه معاندةً في خلافٍ بعيدٍ عن الصواب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتصامُ بالكتاب، وتركُ الاختلاف المذموم فيه."},"action":{"text":"اجعلِ الكتاب حَكَمًا بينك وبين الناس، لا مثارَ خصام."}}]},{"title":"حقيقةُ البرّ، والقصاص، والوصية","range":[177,182],"theme":"البرُّ الجامع، وحياةُ القصاص، والعدلُ في الوصية","verses":[{"n":177,"reflection":{"text":"«ليس البر أن تولوا وجوهكم قبل المشرق والمغرب ولكن البر من آمن بالله واليوم الآخر والملائكة والكتاب والنبيين وآتى المال على حبه ذوي القربى واليتامى والمساكين وابن السبيل والسائلين وفي الرقاب وأقام الصلاة وآتى الزكاة والموفون بعهدهم إذا عاهدوا والصابرين في البأساء والضراء وحين البأس» — البرُّ ليس صورةً بل حقيقةٌ جامعة: إيمانٌ بأركانه، وبذلُ المال على حبِّه، وصلاةٌ وزكاة، ووفاءٌ بالعهد، وصبرٌ عند الشدّة والقتال؛ أولئك الصادقون المتّقون.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ بين إيمان القلب وبذل المال وصبر النفس."},"action":{"text":"زِنْ برَّك بهذه الآية: أين أنت من الإيمان والبذل والوفاء والصبر؟"}},{"n":178,"reflection":{"text":"«يا أيها الذين آمنوا كتب عليكم القصاص في القتلى... فمن عفي له من أخيه شيء فاتباع بالمعروف وأداء إليه بإحسان ذلك تخفيف من ربكم ورحمة» — شُرع القصاصُ عدلًا؛ ومن عفا وليُّ الدم إلى الدية فليُطالبْ بمعروف ويؤدِّ القاتلُ بإحسان؛ وهو تخفيفٌ ورحمةٌ من الله بهذه الأمّة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ حرمة الدم، وشكرُ رحمة العفو والدية."},"action":{"text":"أحسنْ في مطالبك وأداءاتك مع الناس، فالإحسانُ مأمورٌ به حتى في القصاص."}},{"n":179,"reflection":{"text":"«ولكم في القصاص حياة يا أولي الألباب لعلكم تتقون» — في القصاص حياةٌ للمجتمع: إذا علم القاتلُ أنّه يُقتل ارتدع، فحُفظت النفوس؛ وهذا يدركه أولو العقول.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ حكمة الله في أحكامه ورحمتِها بالخلق."},"action":{"text":"تأمّلْ كيف كان في القصاص — وهو قتلٌ — حياةٌ؛ فثِقْ بحكمة كلِّ حكمٍ شرعيّ."}},{"n":180,"reflection":{"text":"«كتب عليكم إذا حضر أحدكم الموت إن ترك خيرا الوصية للوالدين والأقربين بالمعروف حقا على المتقين» — شُرعت الوصيّةُ للأقربين بالمعروف؛ ثم نُسخ ما كان منها للوارثين بآية المواريث، وبقيت لغير الوارث من الأقارب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ للموت، والعنايةُ بحقوق القرابة."},"action":{"text":"اكتبْ وصيّتك ما دمتَ حيًّا، ولا تنسَ فيها قرابةً محتاجة."}},{"n":181,"reflection":{"text":"«فمن بدله بعد ما سمعه فإنما إثمه على الذين يبدلونه إن الله سميع عليم» — من بدّل الوصيّة بعد سماعها فإثمُه على المبدِّل لا الموصي؛ والله سميعٌ لما أوصى، عليمٌ بمن بدّل.","source":"تفسير السعدي","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"الأمانةُ في تنفيذ وصايا الناس."},"action":{"text":"نفِّذْ وصيّة من ائتمنك كما أوصى، ولا تبدّلْها."}},{"n":182,"reflection":{"text":"«فمن خاف من موص جنفا أو إثما فأصلح بينهم فلا إثم عليه إن الله غفور رحيم» — من علم في الوصيّة ميلًا عن الحقّ أو جورًا فأصلح بين الورثة بالعدل فلا حرج عليه؛ فالله غفورٌ رحيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"السعيُ في الإصلاح ورفعِ الجور."},"action":{"text":"إذا رأيت وصيّةً جائرة فاسعَ في الإصلاح بالعدل بين أهلها."}}]},{"title":"الصيامُ وأحكامه، وقُربُ الله","range":[183,188],"theme":"فرضُ الصيام، وفضلُ رمضان، وإجابةُ الدعاء","verses":[{"n":183,"reflection":{"text":"«يا أيها الذين آمنوا كتب عليكم الصيام كما كتب على الذين من قبلكم لعلكم تتقون» — فُرض الصيامُ كما فُرض على الأمم قبلكم؛ وغايتُه العظمى بلوغُ التقوى بكسر الشهوة ومراقبة الله.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ أنّ غاية الصيام التقوى لا مجرّد الجوع."},"action":{"text":"اجعلْ صيامك مدرسةً للتقوى: احفظْ جوارحك كما حفظت بطنك."}},{"n":184,"reflection":{"text":"«أياما معدودات فمن كان منكم مريضا أو على سفر فعدة من أيام أخر... وأن تصوموا خير لكم إن كنتم تعلمون» — الصيامُ أيامٌ معدودة؛ ورخّص للمريض والمسافر القضاء، ولمن يشقّ عليه جدًّا الفديةُ في أوّل الأمر؛ والصومُ خيرٌ لمن علم فضله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ يُسر الشريعة في رُخصها."},"action":{"text":"خذْ برخص الله عند العذر، واعلمْ أنّ الأصل خيرٌ لك."}},{"n":185,"reflection":{"text":"«شهر رمضان الذي أنزل فيه القرآن هدى للناس وبينات من الهدى والفرقان فمن شهد منكم الشهر فليصمه... يريد الله بكم اليسر ولا يريد بكم العسر» — فضلُ رمضان أنّه شهرُ نزول القرآن هدًى وفرقانًا؛ فمن حضره صحيحًا مقيمًا صامه، واللهُ يريد بكم اليُسر لتُكمِلوا العدّة وتُكبِّروه على هدايته وتشكروه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ رمضان شهرِ القرآن، وشكرُ يُسر الله."},"action":{"text":"اجعلْ لرمضان وِردًا من القرآن، فهو شهرُه."}},{"n":186,"reflection":{"text":"«وإذا سألك عبادي عني فإني قريب أجيب دعوة الداع إذا دعان فليستجيبوا لي وليؤمنوا بي لعلهم يرشدون» — قُربٌ عظيم: الله قريبٌ يجيب دعوة الداعي؛ فليطيعوه ويؤمنوا به رجاءَ الرشد. جاءت بين آيات الصيام لأنّ الدعاء عند الصيام مظنّةُ الإجابة.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":["القريب","المجيب"],"heart_state":{"text":"اليقينُ بقرب الله وإجابته، فيُلحّ في الدعاء."},"action":{"text":"ألحَّ على الله بالدعاء خاصّةً عند فطرك، فهو قريبٌ مجيب."}},{"n":187,"sabab":{"text":"كان الرجلُ في أوّل الأمر إذا نام قبل أن يُفطر حَرُم عليه الطعامُ وقربُ أهله بقيّة ليلته ويومه، فشقّ ذلك على بعض الصحابة وأخبروا النبيَّ ﷺ، فنزل التخفيف.","source":"صحيح البخاري (عن البراء بن عازب)","grade":"ma'thur"},"reflection":{"text":"«أحل لكم ليلة الصيام الرفث إلى نسائكم... وكلوا واشربوا حتى يتبين لكم الخيط الأبيض من الخيط الأسود من الفجر ثم أتموا الصيام إلى الليل... تلك حدود الله فلا تقربوها» — بيّن اللهُ أحكام ليل الصيام رحمةً ويُسرًا، وحدَّ الإمساك بطلوع الفجر والإفطار بالليل، والاعتكاف في المساجد؛ وهذه حدودُ الله فلا تُقرَب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوقوفُ عند حدود الله، وعدمُ تعدّيها."},"action":{"text":"التزمْ حدود الصيام كما شرعها الله، ولا تتساهلْ فيها."}},{"n":188,"reflection":{"text":"«ولا تأكلوا أموالكم بينكم بالباطل وتدلوا بها إلى الحكام لتأكلوا فريقا من أموال الناس بالإثم وأنتم تعلمون» — النهيُ عن أكل الأموال بالباطل (الغشّ والربا والرشوة)، وعن الترافع بالحجج الباطلة لأكل حقوق الناس عن علم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحرّي الحلال في المال، واجتنابُ الباطل."},"action":{"text":"لا تأكلْ مالًا بباطل، ولا ترتشِ ولا تُرشِ، ولا تخاصمْ بحجّةٍ تعلم بطلانها."}}]},{"title":"الأهلّة، والقتالُ المشروع","range":[189,195],"theme":"دفعُ الاعتداء بلا بغي، والإنفاقُ في سبيل الله","verses":[{"n":189,"sabab":{"text":"كانوا في الجاهلية إذا أحرم أحدهم لم يدخل بيته من بابه، بل من ظهره أو نقبٍ فيه، ويرون ذلك برًّا، فنزلت تصحّح المفهوم.","source":"متّفق عليه (البخاري ومسلم عن البراء بن عازب)","grade":"ma'thur"},"reflection":{"text":"«يسألونك عن الأهلة قل هي مواقيت للناس والحج وليس البر بأن تأتوا البيوت من ظهورها ولكن البر من اتقى وأتوا البيوت من أبوابها» — الأهلّةُ مواقيتُ للعبادات والمعاملات؛ والبرُّ ليس في صورةٍ متكلَّفة بل في التقوى، فأتوا الأمور من وجوهها الصحيحة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الأمور من أبوابها الصحيحة، وحقيقةُ البرّ التقوى."},"action":{"text":"ائتِ كلَّ أمرٍ من بابه المشروع، ولا تلتمسْ لحاجتك طريقًا ملتويًا."}},{"n":190,"reflection":{"text":"«وقاتلوا في سبيل الله الذين يقاتلونكم ولا تعتدوا إن الله لا يحب المعتدين» — أُذن بقتال من يقاتلكم دفاعًا عن الدين؛ مع النهي عن الاعتداء بقتل من لا يُقاتل، فالله لا يحبّ المعتدين.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العدلُ حتى في القتال، ومجانبةُ العدوان."},"action":{"text":"التزمِ العدل مع من خاصمك، ولا تتجاوزْ حدَّ ردّ الظلم."}},{"n":191,"reflection":{"text":"«واقتلوهم حيث ثقفتموهم وأخرجوهم من حيث أخرجوكم والفتنة أشد من القتل... فإن قاتلوكم فاقتلوهم كذلك جزاء الكافرين» — أحكامٌ في قتال المعتدين الذين أخرجوا المسلمين؛ والفتنةُ (الصدُّ عن الدين والشرك) أعظمُ جرمًا من القتل.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعظامُ فتنة الصدّ عن دين الله."},"action":{"text":"اثبتْ على دينك ولا تُفتَنْ عنه، فالفتنةُ في الدين أشدُّ من القتل."}},{"n":192,"reflection":{"text":"«فإن انتهوا فإن الله غفور رحيم» — فإن كفّوا عن القتال والكفر فالله غفورٌ لما سلف رحيمٌ بعباده؛ فبابُ التوبة مفتوحٌ حتى للمحاربين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"قبولُ رجوع المسيء، وسعةُ رحمة الله."},"action":{"text":"إذا كفّ عنك من آذاك فاقبلْ، ولا تحملْ ضغينةً بعد انتهائه."}},{"n":193,"reflection":{"text":"«وقاتلوهم حتى لا تكون فتنة ويكون الدين لله فإن انتهوا فلا عدوان إلا على الظالمين» — غايةُ القتال المشروع: دفعُ الفتنة عن الدين وإخلاصُ العبادة لله؛ فإن انتهوا فلا يُعتدى إلا على من ظلم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن تكون الغاية إعلاءَ دين الله لا الانتقام."},"action":{"text":"اجعلْ غايتك في كلّ نزاعٍ إحقاقَ الحقّ لا الانتصار للنفس."}},{"n":194,"reflection":{"text":"«الشهر الحرام بالشهر الحرام والحرمات قصاص فمن اعتدى عليكم فاعتدوا عليه بمثل ما اعتدى عليكم واتقوا الله واعلموا أن الله مع المتقين» — الحرماتُ يُقتصّ فيها بالمثل لا بالزيادة؛ ومع القصاص أُمروا بالتقوى، فمعيّةُ الله للمتّقين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العدلُ بالمثل، والتقوى حتى عند الانتصار."},"action":{"text":"إذا انتصرتَ لحقّك فلا تتجاوزِ المِثل، واتّقِ الله في ذلك."}},{"n":195,"reflection":{"text":"«وأنفقوا في سبيل الله ولا تلقوا بأيديكم إلى التهلكة وأحسنوا إن الله يحب المحسنين» — أمرٌ بالإنفاق في سبيل الله، ونهيٌ عن الإلقاء بالنفس إلى الهلاك (ومنه تركُ الإنفاق حتى يقوى العدو)، والحثُّ على الإحسان؛ فالله يحبّ المحسنين.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ المال في الخير، وإحسانُ العمل."},"action":{"text":"أنفقْ في سبيل الله اليوم، وأحسنْ في عملك، فالله يحبّ المحسنين."}}]},{"title":"الحجُّ وآدابه، والدعاءُ الجامع","range":[196,203],"theme":"إتمامُ النسك، وخيرُ الزاد التقوى","verses":[{"n":196,"reflection":{"text":"«وأتموا الحج والعمرة لله فإن أحصرتم فما استيسر من الهدي... واتقوا الله واعلموا أن الله شديد العقاب» — أمرٌ بإتمام الحجّ والعمرة خالصَين لله؛ وبيانُ حكم الإحصار بالمرض أو العدوّ، والفديةِ، والتمتّع؛ مع التقوى والخوف من عقاب الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ النسك لله، وإتمامُه على وجهه."},"action":{"text":"إذا حججتَ أو اعتمرتَ فأخلصْ لله وأتمَّ النسك كما شُرع."}},{"n":197,"reflection":{"text":"«الحج أشهر معلومات فمن فرض فيهن الحج فلا رفث ولا فسوق ولا جدال في الحج... وتزودوا فإن خير الزاد التقوى واتقون يا أولي الألباب» — للحجّ أشهرٌ معلومة؛ ومن أحرم فليجتنبِ الرفثَ والفسوقَ والجدال؛ وخيرُ ما يُتزوَّد به التقوى.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تزكيةُ النسك بترك الرفث والفسوق والجدال."},"action":{"text":"اجعلْ خير زادك التقوى في سفرك وحضرك، لا زاد الأبدان فقط."}},{"n":198,"reflection":{"text":"«ليس عليكم جناح أن تبتغوا فضلا من ربكم فإذا أفضتم من عرفات فاذكروا الله عند المشعر الحرام واذكروه كما هداكم» — أُبيح للحاجّ التكسّبُ بالتجارة؛ وأُمر بذكر الله عند المشعر الحرام بعد الإفاضة من عرفات، شكرًا على الهداية.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ الله على الهداية بذكره في المشاعر."},"action":{"text":"أكثِرْ من ذكر الله في مواطن العبادة، شكرًا على هدايته لك."}},{"n":199,"reflection":{"text":"«ثم أفيضوا من حيث أفاض الناس واستغفروا الله إن الله غفور رحيم» — أُمروا بالإفاضة من عرفات كسائر الناس (لا كما كانت قريش تتميّز)، وبالاستغفار؛ فالله غفورٌ رحيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"التواضعُ مع الناس، ولزومُ الاستغفار."},"action":{"text":"اختمْ أعمالك الصالحة بالاستغفار، فهو جبرٌ للنقص."}},{"n":200,"reflection":{"text":"«فإذا قضيتم مناسككم فاذكروا الله كذكركم آباءكم أو أشد ذكرا فمن الناس من يقول ربنا آتنا في الدنيا وما له في الآخرة من خلاق» — بعد المناسك أُمروا بالإكثار من ذكر الله؛ وذُمّ من قصر همّه على الدنيا فلا نصيب له في الآخرة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يكون همُّ العبد الآخرةَ لا الدنيا وحدها."},"action":{"text":"لا تجعلْ دعاءك كلَّه للدنيا؛ اطلبْ آخرتك أوّلًا."}},{"n":201,"reflection":{"text":"«ومنهم من يقول ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار» — دعاءُ المؤمن الجامع: حسنةَ الدنيا (رزقًا وعافيةً وعلمًا وعملًا) وحسنةَ الآخرة (الجنّة)، والوقايةَ من النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الجمعُ في الدعاء بين خير الدنيا والآخرة."},"action":{"text":"أكثِرْ من دعاء «ربنا آتنا في الدنيا حسنة وفي الآخرة حسنة وقنا عذاب النار»."}},{"n":202,"reflection":{"text":"«أولئك لهم نصيب مما كسبوا والله سريع الحساب» — أهلُ الدعاء الجامع لهم نصيبٌ وافرٌ من ثواب ما كسبوا؛ والله سريعُ الحساب لا يشغله شأنٌ عن شأن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في ثواب الكسب الصالح، واستحضارُ سرعة الحساب."},"action":{"text":"أكثِرْ من الكسب الصالح، فالله سريعُ الحساب لا يضيع لديه شيء."}},{"n":203,"reflection":{"text":"«واذكروا الله في أيام معدودات فمن تعجل في يومين فلا إثم عليه ومن تأخر فلا إثم عليه لمن اتقى واتقوا الله واعلموا أنكم إليه تحشرون» — ذكرُ الله في أيام التشريق (التكبير)؛ ومن تعجّل النفرَ في يومين أو تأخّر فلا حرج، والعبرةُ بالتقوى، واستحضارِ الحشر إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من ذكر الله في مواسم الخير، واستحضارُ الحشر."},"action":{"text":"أكثِرْ من التكبير والذكر في أيام العيد والتشريق."}}]},{"title":"المنافقُ المفسد، وبائعُ نفسه لله، والدخولُ في السلم","range":[204,214],"theme":"صدقُ الباطن، والاستسلامُ للإسلام كلِّه، وسنّةُ الابتلاء","verses":[{"n":204,"reflection":{"text":"«ومن الناس من يعجبك قوله في الحياة الدنيا ويشهد الله على ما في قلبه وهو ألد الخصام» — صنفٌ يُعجبك ظاهرُ قوله ويحلف على صدقه، وباطنُه خبيثٌ شديدُ الخصومة للحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاغترار بحلاوة القول دون العمل."},"action":{"text":"لا تحكمْ على الناس بمعسول الكلام، بل بصدق العمل."}},{"n":205,"reflection":{"text":"«وإذا تولى سعى في الأرض ليفسد فيها ويهلك الحرث والنسل والله لا يحب الفساد» — إذا انصرف عنك أظهر حقيقتَه: سعيٌ في الإفساد وإهلاكِ الزرع والنسل؛ والله لا يحبّ الفساد.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"بغضُ الفساد في الأرض، وحبُّ الإصلاح."},"action":{"text":"كنْ من المصلحين في الأرض لا المفسدين، ولو في الصغائر."}},{"n":206,"reflection":{"text":"«وإذا قيل له اتق الله أخذته العزة بالإثم فحسبه جهنم ولبئس المهاد» — إذا نُصح بتقوى الله حملته الأنَفةُ والكبرُ على التمادي في الإثم؛ فجزاؤه جهنم وبئس الفراش.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"قبولُ النصيحة بتقوى الله، وتركُ الكبر."},"action":{"text":"إذا قيل لك اتقِ الله فاخضعْ وارجعْ، ولا تأخذْك العزّة بالإثم."}},{"n":207,"reflection":{"text":"«ومن الناس من يشري نفسه ابتغاء مرضاة الله والله رؤوف بالعباد» — في مقابل المفسد: مؤمنٌ يبيع نفسه لله يبذلها في طاعته ابتغاء مرضاته؛ والله رؤوفٌ بعباده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الرؤوف"],"heart_state":{"text":"بذلُ النفس لله ابتغاءَ رضاه."},"action":{"text":"قدِّمْ من نفسك ووقتك لله ابتغاء مرضاته، لا رياءَ الناس."}},{"n":208,"reflection":{"text":"«يا أيها الذين آمنوا ادخلوا في السلم كافة ولا تتبعوا خطوات الشيطان إنه لكم عدو مبين» — ادخلوا في الإسلام والطاعة كلِّها بجميع شرائعه، ولا تتّبعوا خطوات الشيطان الذي يجزّئكم؛ فهو عدوٌّ مبين.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستسلامُ للإسلام كلِّه لا بعضِه."},"action":{"text":"خذِ الدين كلَّه، ولا تدعْ بابًا من الطاعة بحجّة المشقّة."}},{"n":209,"reflection":{"text":"«فإن زللتم من بعد ما جاءتكم البينات فاعلموا أن الله عزيز حكيم» — إن زللتم بعد وضوح البيّنات فاعلموا أنّ الله عزيزٌ لا يُعجزه أحد، حكيمٌ في عقابه وثوابه.","source":"تفسير السعدي","grade":"ma'thur"},"names":["العزيز","الحكيم"],"heart_state":{"text":"الثباتُ بعد وضوح الحجّة، وخشيةُ العزيز الحكيم."},"action":{"text":"احذرِ الزلل بعد العلم؛ فإنّ عقوبته أعظم."}},{"n":210,"reflection":{"text":"«هل ينظرون إلا أن يأتيهم الله في ظلل من الغمام والملائكة وقضي الأمر وإلى الله ترجع الأمور» — تهديدٌ للمعرضين: هل ينتظرون إلا مجيء الله للفصل يوم القيامة حيث يُقضى الأمر، وإلى الله مرجعُ كلّ شيء؟","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ يوم الفصل الذي ترجع فيه الأمور إلى الله."},"action":{"text":"بادرْ بالطاعة قبل يومٍ يُقضى فيه الأمر ولا مردَّ له."}},{"n":211,"reflection":{"text":"«سل بني إسرائيل كم آتيناهم من آية بينة ومن يبدل نعمة الله من بعد ما جاءته فإن الله شديد العقاب» — كثرةُ آيات الله لبني إسرائيل ثم تبديلُهم؛ ومن بدّل نعمة الله كفرًا بعد مجيئها فإنّ الله شديد العقاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ النعمة بحفظها لا تبديلِها بالكفر."},"action":{"text":"احفظْ نعم الله عليك بطاعته، ولا تستعملْها في معصيته."}},{"n":212,"reflection":{"text":"«زين للذين كفروا الحياة الدنيا ويسخرون من الذين آمنوا والذين اتقوا فوقهم يوم القيامة والله يرزق من يشاء بغير حساب» — زُيّنت الدنيا للكفار فسخروا من فقراء المؤمنين؛ والمتّقون فوقهم يوم القيامة منزلةً، والله يرزق من يشاء بلا حساب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عدمُ الاغترار بزينة الدنيا وسخرية أهلها."},"action":{"text":"لا يحزنك استخفافُ أهل الدنيا بك على دينك؛ فالعاقبةُ للمتّقين."}},{"n":213,"reflection":{"text":"«كان الناس أمة واحدة فبعث الله النبيين مبشرين ومنذرين وأنزل معهم الكتاب بالحق ليحكم بين الناس فيما اختلفوا فيه... فهدى الله الذين آمنوا لما اختلفوا فيه من الحق بإذنه» — كان الناسُ على التوحيد فاختلفوا، فبعث اللهُ النبيين وأنزل الكتب ليحكم بين الناس؛ فهدى اللهُ المؤمنين للحقّ بإذنه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمة الهداية للحقّ عند اختلاف الناس."},"action":{"text":"اسألِ الله أن يهديك للحقّ فيما اختلف فيه الناس."}},{"n":214,"reflection":{"text":"«أم حسبتم أن تدخلوا الجنة ولما يأتكم مثل الذين خلوا من قبلكم مستهم البأساء والضراء وزلزلوا حتى يقول الرسول والذين آمنوا معه متى نصر الله ألا إن نصر الله قريب» — الجنةُ لا تُنال بالتمنّي بل بالابتلاء والصبر كما ابتُلي من قبلكم حتى استبطؤوا النصر؛ ألا إنّ نصر الله قريب.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ على الابتلاء، واليقينُ بقرب نصر الله."},"action":{"text":"إذا اشتدّ البلاء فاصبرْ وأيقنْ أنّ نصر الله قريب."}}]},{"title":"مسائلُ السائلين: الإنفاق، والقتال، والخمر، واليتامى، والنكاح","range":[215,221],"theme":"أجوبةٌ جامعةٌ لأسئلة الصحابة","verses":[{"n":215,"reflection":{"text":"«يسألونك ماذا ينفقون قل ما أنفقتم من خير فللوالدين والأقربين واليتامى والمساكين وابن السبيل وما تفعلوا من خير فإن الله به عليم» — سألوا عمّن يُنفَق عليه، فبيّن الأولى فالأولى: الوالدان ثم الأقربون ثم اليتامى والمساكين وابن السبيل؛ وكلُّ خيرٍ فالله به عليم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العليم"],"heart_state":{"text":"ترتيبُ الأولى بالإحسان في الإنفاق."},"action":{"text":"ابدأْ بإنفاقك على والديك وأقاربك المحتاجين قبل غيرهم."}},{"n":216,"reflection":{"text":"«كتب عليكم القتال وهو كره لكم وعسى أن تكرهوا شيئا وهو خير لكم وعسى أن تحبوا شيئا وهو شر لكم والله يعلم وأنتم لا تعلمون» — فُرض القتالُ وهو ثقيلٌ على النفوس؛ وقد يكره العبدُ ما هو خيرٌ له ويحبّ ما هو شرٌّ له، والله يعلم ما لا تعلمون.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":["العليم"],"heart_state":{"text":"التسليمُ لاختيار الله، فكم في المكروه من خير."},"action":{"text":"ارضَ بما اختاره الله لك؛ فربّ مكروهٍ فيه خيرك، وربّ محبوبٍ فيه شرّك."}},{"n":217,"reflection":{"text":"«يسألونك عن الشهر الحرام قتال فيه قل قتال فيه كبير وصد عن سبيل الله وكفر به والمسجد الحرام وإخراج أهله منه أكبر عند الله والفتنة أكبر من القتل» — القتالُ في الشهر الحرام ذنبٌ كبير، لكنّ صدَّ الكفار عن سبيل الله وعن المسجد الحرام وإخراجَ أهله أعظمُ جرمًا، والفتنةُ عن الدين أكبرُ من القتل. ومن يرتدّ فيمت كافرًا حبط عمله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ حرمة الدين وبيت الله، والحذرُ من الردّة."},"action":{"text":"اثبتْ على دينك مهما اشتدّ الأذى؛ فالردّةُ حبوطٌ للعمل."}},{"n":218,"reflection":{"text":"«إن الذين آمنوا والذين هاجروا وجاهدوا في سبيل الله أولئك يرجون رحمة الله والله غفور رحيم» — أهلُ الإيمان والهجرة والجهاد هم أهلُ رجاء رحمة الله الصادق؛ فالله غفورٌ رحيم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"رجاءُ رحمة الله مقرونًا بالعمل الصالح."},"action":{"text":"اجعلْ رجاءك لرحمة الله مصحوبًا بعملٍ يصدّقه: إيمانٍ وطاعةٍ وبذل."}},{"n":219,"reflection":{"text":"«يسألونك عن الخمر والميسر قل فيهما إثم كبير ومنافع للناس وإثمهما أكبر من نفعهما ويسألونك ماذا ينفقون قل العفو» — في الخمر والميسر إثمٌ كبير يفوق ما فيهما من منفعةٍ عاجلة؛ وهذا تمهيدٌ لتحريمهما. والإنفاقُ يكون من العفو (الزائد عن الحاجة).","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اجتنابُ ما إثمُه أكبر من نفعه، والاعتدالُ في الإنفاق."},"action":{"text":"اجتنبِ الخمر والميسر وكلَّ ما إثمُه أكبر من نفعه، وأنفقْ من فضل مالك."}},{"n":220,"reflection":{"text":"«في الدنيا والآخرة ويسألونك عن اليتامى قل إصلاح لهم خير وإن تخالطوهم فإخوانكم والله يعلم المفسد من المصلح ولو شاء الله لأعنتكم إن الله عزيز حكيم» — الأصلحُ لليتامى إصلاحُ أموالهم؛ ومخالطتُهم بالمعروف جائزة فهم إخوانكم؛ والله يعلم من يقصد الإفساد ممّن يقصد الإصلاح.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العزيز","الحكيم"],"heart_state":{"text":"قصدُ الإصلاح في التعامل مع أموال الضعفاء."},"action":{"text":"إذا وليتَ مال يتيمٍ فاقصدْ إصلاحه، فالله يعلم المصلح من المفسد."}},{"n":221,"reflection":{"text":"«ولا تنكحوا المشركات حتى يؤمن ولأمة مؤمنة خير من مشركة ولو أعجبتكم ولا تنكحوا المشركين حتى يؤمنوا... أولئك يدعون إلى النار والله يدعو إلى الجنة والمغفرة بإذنه» — النهيُ عن نكاح المشركين والمشركات؛ فالأمةُ المؤمنة خيرٌ من حرّةٍ مشركة ولو أعجبت؛ لأنّ أهل الشرك يدعون إلى النار، والله يدعو إلى الجنة والمغفرة.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقديمُ الدين على الجمال والنسب في اختيار القرين."},"action":{"text":"اختَرْ لنكاحك ولمصاحبتك أهلَ الدين؛ فقرينُ السوء يدعو إلى النار."}}]},{"title":"أحكامُ الأسرة: المحيض، والأيمان، والطلاق، والعِدَد، والرضاع","range":[222,237],"theme":"رحمةُ التشريع في بيتِ المسلم","verses":[{"n":222,"sabab":{"text":"كان اليهودُ إذا حاضت المرأةُ لم يؤاكلوها ولم يجالسوها في البيت، فسأل الصحابةُ النبيَّ ﷺ، فنزلت، فقال ﷺ: «اصنعوا كلَّ شيءٍ إلا النكاح».","source":"صحيح مسلم (عن أنس بن مالك)","grade":"ma'thur"},"reflection":{"text":"«ويسألونك عن المحيض قل هو أذى فاعتزلوا النساء في المحيض ولا تقربوهن حتى يطهرن... إن الله يحب التوابين ويحب المتطهرين» — الحيضُ أذًى، فيُعتزل جماعُ الحائض حتى تطهر وتغتسل؛ والله يحبّ التوابين من الذنوب والمتطهّرين من الأحداث والأقذار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محبّةُ الله للتوّابين المتطهّرين."},"action":{"text":"تطهّرْ من الذنوب بالتوبة، ومن الأحداث بالوضوء والغسل؛ فالله يحبّ ذلك."}},{"n":223,"reflection":{"text":"«نساؤكم حرث لكم فأتوا حرثكم أنى شئتم وقدموا لأنفسكم واتقوا الله واعلموا أنكم ملاقوه وبشر المؤمنين» — أُبيح إتيانُ الزوجة في موضع الحرث (النسل) كيف شئتم؛ وحُثّ على تقديم العمل الصالح، وتقوى الله، واستحضارِ لقائه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ لقاء الله حتى في شؤون البيت."},"action":{"text":"قدّمْ لنفسك عملًا صالحًا اليوم، واستحضرْ أنّك ملاقٍ ربّك."}},{"n":224,"reflection":{"text":"«ولا تجعلوا الله عرضة لأيمانكم أن تبروا وتتقوا وتصلحوا بين الناس والله سميع عليم» — لا تجعلوا الحلف بالله ذريعةً لتركِ البرّ والتقوى والإصلاح بين الناس (كأن يحلف ألّا يصل رحمًا)؛ فالله سميعٌ عليم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"ألّا يكون اليمينُ حاجزًا عن الخير."},"action":{"text":"إن حلفتَ على تركِ خيرٍ فكفِّرْ عن يمينك وائتِ الذي هو خير."}},{"n":225,"reflection":{"text":"«لا يؤاخذكم الله باللغو في أيمانكم ولكن يؤاخذكم بما كسبت قلوبكم والله غفور حليم» — لا يؤاخذ اللهُ بلغو اليمين (ما يجري على اللسان بلا قصد)، وإنّما بما قصدته القلوب؛ فهو غفورٌ حليم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الحليم"],"heart_state":{"text":"شكرُ حلم الله ومغفرته، وضبطُ قصد القلب."},"action":{"text":"تحرَّ الصدق في يمينك المقصودة، فالمؤاخذةُ على قصد القلب."}},{"n":226,"reflection":{"text":"«للذين يؤلون من نسائهم تربص أربعة أشهر فإن فاءوا فإن الله غفور رحيم» — من حلف ألّا يقرب زوجته (الإيلاء) يُنتظر أربعة أشهر؛ فإن رجع وكفّر عن يمينه فالله غفورٌ رحيم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الرحيم"],"heart_state":{"text":"المبادرةُ إلى الصلح ورأبِ الصدع."},"action":{"text":"إذا هجرتَ في غضب فبادرْ بالرجوع والإصلاح قبل استحكام القطيعة."}},{"n":227,"reflection":{"text":"«وإن عزموا الطلاق فإن الله سميع عليم» — وإن أصرّوا على الطلاق بعد المدّة فهو حقُّهم؛ والله سميعٌ لأقوالهم عليمٌ بنيّاتهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"استحضارُ سمع الله وعلمه في أحوال البيوت."},"action":{"text":"راقبِ الله في معاملة أهلك، فهو سميعٌ عليمٌ بما بينكم."}},{"n":228,"reflection":{"text":"«والمطلقات يتربصن بأنفسهن ثلاثة قروء... وبعولتهن أحق بردهن في ذلك إن أرادوا إصلاحا ولهن مثل الذي عليهن بالمعروف وللرجال عليهن درجة والله عزيز حكيم» — عدّةُ المطلقة ثلاثةُ قروء؛ وللزوج ردُّها في العدّة إن أراد الإصلاح؛ وللزوجة حقوقٌ كما عليها بالمعروف، وللرجل درجةُ القِوامة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["العزيز","الحكيم"],"heart_state":{"text":"أداءُ الحقوق الزوجية بالمعروف والعدل."},"action":{"text":"أدِّ لأهلك حقوقهم بالمعروف، ولا تستعملِ القوامةَ في ظلم."}},{"n":229,"reflection":{"text":"«الطلاق مرتان فإمساك بمعروف أو تسريح بإحسان... تلك حدود الله فلا تعتدوها» — الطلاقُ الذي تُملَك فيه الرجعةُ مرّتان؛ ثم إمساكٌ بمعروف أو تسريحٌ بإحسان؛ وبيّن حكم الخلع؛ تلك حدودُ الله فلا تُتعدَّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الوقوفُ عند حدود الله في الطلاق."},"action":{"text":"إن طلّقتَ فأمسكْ بمعروفٍ أو سرّحْ بإحسان، ولا تتعدَّ حدود الله."}},{"n":230,"reflection":{"text":"«فإن طلقها فلا تحل له من بعد حتى تنكح زوجا غيره فإن طلقها فلا جناح عليهما أن يتراجعا إن ظنا أن يقيما حدود الله» — الطلقةُ الثالثة تُحرّم الزوجةَ حتى تنكح زوجًا آخر نكاحَ رغبة؛ فإن طلّقها الثاني جاز رجوعُها للأوّل إن ظنّا إقامة حدود الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ عقد النكاح، وعدمُ التلاعب بالطلاق."},"action":{"text":"لا تتلاعبْ بالطلاق؛ فله حدودٌ إذا تجاوزتها حُرّمت عليك زوجتك."}},{"n":231,"reflection":{"text":"«وإذا طلقتم النساء فبلغن أجلهن فأمسكوهن بمعروف أو سرحوهن بمعروف ولا تمسكوهن ضرارا لتعتدوا ومن يفعل ذلك فقد ظلم نفسه... واذكروا نعمت الله عليكم وما أنزل عليكم من الكتاب والحكمة يعظكم به» — عند انقضاء العدّة: إمساكٌ بمعروف أو تسريحٌ بمعروف؛ ونهيٌ عن مراجعتها للإضرار بها؛ فمن فعل ذلك ظلم نفسه، ولا يُتّخذ دينُ الله هزوًا.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحريمُ الإضرار بالزوجة، وتعظيمُ حرمات الله."},"action":{"text":"لا تُمسكْ زوجتك لتضرّها؛ إمّا معروفٌ في الإمساك أو إحسانٌ في الفراق."}},{"n":232,"reflection":{"text":"«وإذا طلقتم النساء فبلغن أجلهن فلا تعضلوهن أن ينكحن أزواجهن إذا تراضوا بينهم بالمعروف» — نهيٌ للأولياء عن منع المطلّقة من الرجوع إلى زوجها إذا تراضيا بالمعروف؛ ذلك أزكى وأطهر، والله يعلم وأنتم لا تعلمون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تركُ التعنّت في تزويج المرأة ممّن ترضاه بالمعروف."},"action":{"text":"لا تعضلْ من تحت ولايتك عن نكاحِ كُفءٍ ترضاه بالمعروف."}},{"n":233,"reflection":{"text":"«والوالدات يرضعن أولادهن حولين كاملين لمن أراد أن يتم الرضاعة وعلى المولود له رزقهن وكسوتهن بالمعروف لا تكلف نفس إلا وسعها» — الرضاعةُ الكاملةُ حولان؛ وعلى الأب نفقةُ الأمّ وكسوتُها بالمعروف؛ لا تُكلَّف نفسٌ فوق طاقتها، ولا يُضارُّ والدٌ ولا مولود.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"العدلُ في حقوق الأمّ والطفل، ورفعُ الضرر."},"action":{"text":"أدِّ حقوق أهلك وأطفالك بالمعروف بلا إضرارٍ ولا تقصير."}},{"n":234,"reflection":{"text":"«والذين يتوفون منكم ويذرون أزواجا يتربصن بأنفسهن أربعة أشهر وعشرا فإذا بلغن أجلهن فلا جناح عليكم فيما فعلن في أنفسهن بالمعروف» — عدّةُ المتوفّى عنها زوجُها أربعةُ أشهرٍ وعشر؛ فإذا انقضت فلا حرج فيما تفعله بالمعروف من زينةٍ أو نكاح؛ والله بما تعملون خبير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الخبير"],"heart_state":{"text":"الالتزامُ بحدود الله في العِدد وفاءً وطهرًا."},"action":{"text":"احترمْ أحكام العدّة وحقوق المتوفّى عنها، فالله خبيرٌ بما تعملون."}},{"n":235,"reflection":{"text":"«ولا جناح عليكم فيما عرضتم به من خطبة النساء أو أكننتم في أنفسكم علم الله أنكم ستذكرونهن ولكن لا تواعدوهن سرا... واعلموا أن الله يعلم ما في أنفسكم فاحذروه» — أُبيح التعريضُ بخطبة المعتدّة (لا التصريح ولا المواعدةُ سرًّا)؛ ولا يُعقد النكاح حتى تنقضي العدّة؛ واحذروا الله العالمَ بما في النفوس.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغفور","الحليم"],"heart_state":{"text":"مراقبةُ الله فيما تُكِنّه النفوس."},"action":{"text":"احفظْ حدود الله في المعاملات، واحذرْه فهو يعلم ما في نفسك."}},{"n":236,"reflection":{"text":"«لا جناح عليكم إن طلقتم النساء ما لم تمسوهن أو تفرضوا لهن فريضة ومتعوهن على الموسع قدره وعلى المقتر قدره متاعا بالمعروف حقا على المحسنين» — من طلّق قبل الدخول وقبل فرض المهر فلا مهرَ عليه، لكن يُمتّعها بمعروفٍ بحسب سعته؛ حقًّا على المحسنين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإحسانُ إلى المطلّقة جبرًا لخاطرها."},"action":{"text":"أحسنْ إلى من فارقتَها بمتعةٍ تجبر خاطرها بحسب استطاعتك."}},{"n":237,"reflection":{"text":"«وإن طلقتموهن من قبل أن تمسوهن وقد فرضتم لهن فريضة فنصف ما فرضتم إلا أن يعفون أو يعفو الذي بيده عقدة النكاح وأن تعفوا أقرب للتقوى ولا تنسوا الفضل بينكم» — من طلّق قبل الدخول بعد فرض المهر فلها نصفُه، إلا أن تعفو أو يعفو الزوج بكامله؛ والعفوُ أقربُ للتقوى، فلا يُنسى الفضلُ بين الناس.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ العفو والفضل على استيفاء الحقّ."},"action":{"text":"سامحْ في بعض حقّك عند الفراق؛ فالعفو أقرب للتقوى."}}]},{"title":"المحافظةُ على الصلاة، ومتاعُ المطلّقات","range":[238,242],"theme":"الصلاةُ في قلب الأحكام، وبيانُ الله آياته","verses":[{"n":238,"reflection":{"text":"«حافظوا على الصلوات والصلاة الوسطى وقوموا لله قانتين» — أمرٌ بالمحافظة على الصلوات كلِّها، وخصّ الوسطى (وهي العصر في أصحّ الأقوال) بالتأكيد؛ والقيامُ لله بخشوعٍ وطاعة. جاء الأمرُ بالصلاة في وسط أحكام الأسرة تنبيهًا على عظيم شأنها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الصلاة، والقيامُ لله خاشعًا قانتًا."},"action":{"text":"حافظْ على صلواتك في أوقاتها، وأحسنْ خشوعك فيها، خاصّةً العصر."}},{"n":239,"reflection":{"text":"«فإن خفتم فرجالا أو ركبانا فإذا أمنتم فاذكروا الله كما علمكم ما لم تكونوا تعلمون» — عند الخوف تُصلّى ماشين أو راكبين على أيّ حال؛ فإذا أمنتم فأتمّوها واذكروا الله شكرًا على ما علّمكم. فالصلاة لا تسقط بحال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المحافظةُ على الصلاة حتى في أشدّ الأحوال."},"action":{"text":"لا تدعِ الصلاة لعذرٍ يمكن معه أداؤها ولو على حال."}},{"n":240,"reflection":{"text":"«والذين يتوفون منكم ويذرون أزواجا وصية لأزواجهم متاعا إلى الحول غير إخراج فإن خرجن فلا جناح عليكم في ما فعلن في أنفسهن من معروف» — كان يُوصى للزوجة بالسكنى والنفقة حولًا؛ وهذا الحكمُ منسوخٌ بعدّة الأشهر الأربعة والعشر وبآية الميراث، لكن يُتلى إعظامًا لكتاب الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرحمةُ بالأرملة وحفظُ حقّها."},"action":{"text":"أحسنْ إلى الأرامل وأدِّ حقوقهن، فذاك من البرّ."}},{"n":241,"reflection":{"text":"«وللمطلقات متاع بالمعروف حقا على المتقين» — لكلّ مطلّقةٍ متاعٌ يجبر خاطرها بحسب حال الزوج؛ حقًّا واجبًا على المتّقين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"جبرُ خاطر المطلّقة من علامات التقوى."},"action":{"text":"إذا فارقتَ زوجةً فأتبعْها بمتاعٍ ومعروفٍ يجبر خاطرها."}},{"n":242,"reflection":{"text":"«كذلك يبين الله لكم آياته لعلكم تعقلون» — بمثل هذا البيان الشافي يوضّح اللهُ لكم أحكامه وآياته؛ لتعقلوها فتعملوا بها.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمة البيان، والعملُ بمقتضاه."},"action":{"text":"لا تكتفِ بفهم أحكام الله؛ اعملْ بها فذاك ثمرةُ العقل."}}]},{"title":"قصصُ القدر والقتال: طالوت وجالوت وداود","range":[243,252],"theme":"لا مفرَّ من القدر، والقلّةُ المؤمنة تغلب بإذن الله","verses":[{"n":243,"reflection":{"text":"«ألم تر إلى الذين خرجوا من ديارهم وهم ألوف حذر الموت فقال لهم الله موتوا ثم أحياهم إن الله لذو فضل على الناس ولكن أكثر الناس لا يشكرون» — قومٌ فرّوا من الموت بالآلاف فأماتهم اللهُ ثم أحياهم؛ فلا مفرَّ من قدره، وهو ذو فضلٍ على الناس لكنّ أكثرهم لا يشكرون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ لا مهربَ من قدر الله، وشكرُ فضله."},"action":{"text":"لا تفرَّ من طاعةٍ أو جهادٍ خوفَ الموت؛ فالآجالُ بيد الله."}},{"n":244,"reflection":{"text":"«وقاتلوا في سبيل الله واعلموا أن الله سميع عليم» — أمرٌ بالقتال في سبيل الله، مع استحضار أنّه سميعٌ لأقوالكم عليمٌ بنيّاتكم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"بذلُ النفس في سبيل الله مع إخلاص النيّة."},"action":{"text":"أخلصْ نيّتك في كلّ عملٍ تبذل فيه جهدك لله."}},{"n":245,"reflection":{"text":"«من ذا الذي يقرض الله قرضا حسنا فيضاعفه له أضعافا كثيرة والله يقبض ويبسط وإليه ترجعون» — حضٌّ لطيف على الإنفاق: من ينفق في سبيل الله كأنّه يُقرض اللهَ فيضاعفه أضعافًا؛ والله يقبض الرزق ويبسطه، وإليه المرجع.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"بذلُ المال يقينًا بمضاعفة الله وخلَفِه."},"action":{"text":"أقرضِ اللهَ اليوم بصدقةٍ، وأيقنْ أنّه يضاعفها أضعافًا."}},{"n":246,"reflection":{"text":"«ألم تر إلى الملإ من بني إسرائيل من بعد موسى إذ قالوا لنبي لهم ابعث لنا ملكا نقاتل في سبيل الله قال هل عسيتم إن كتب عليكم القتال ألا تقاتلوا... فلما كتب عليهم القتال تولوا إلا قليلا منهم» — طلبوا ملكًا ليقاتلوا، فلمّا فُرض القتالُ تولّى أكثرهم؛ ضعفُ العزيمة عند الجدّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"صدقُ العزيمة عند التكليف لا مجرّد التمنّي."},"action":{"text":"إذا عزمتَ على خيرٍ فامضِ فيه عند الجدّ، ولا تتراجعْ."}},{"n":247,"reflection":{"text":"«وقال لهم نبيهم إن الله قد بعث لكم طالوت ملكا قالوا أنى يكون له الملك علينا ونحن أحق بالملك منه ولم يؤت سعة من المال قال إن الله اصطفاه عليكم وزاده بسطة في العلم والجسم والله يؤتي ملكه من يشاء» — اعترضوا على ملك طالوت لفقره؛ فبيّن أنّ الله اصطفاه وزاده علمًا وقوّة، والملكُ بيد الله يؤتيه من يشاء لا بالمال.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":["الواسع","العليم"],"heart_state":{"text":"الرضا باختيار الله، وتقديمُ العلم والكفاءة على المال."},"action":{"text":"قدِّرِ الناس بعلمهم وتقواهم لا بأموالهم وأنسابهم."}},{"n":248,"reflection":{"text":"«وقال لهم نبيهم إن آية ملكه أن يأتيكم التابوت فيه سكينة من ربكم وبقية مما ترك آل موسى وآل هارون تحمله الملائكة إن في ذلك لآية لكم إن كنتم مؤمنين» — جعل اللهُ آيةَ ملكه رجوعَ التابوت الذي فيه سكينةٌ وبقايا مما ترك آل موسى وهارون تحمله الملائكة؛ آيةً للمؤمنين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ السكينة التي ينزلها الله على القلوب."},"action":{"text":"اطلبْ سكينة قلبك بذكر الله وطاعته، فهي من عنده."}},{"n":249,"reflection":{"text":"«فلما فصل طالوت بالجنود قال إن الله مبتليكم بنهر فمن شرب منه فليس مني... فشربوا منه إلا قليلا منهم... قال الذين يظنون أنهم ملاقو الله كم من فئة قليلة غلبت فئة كثيرة بإذن الله والله مع الصابرين» — ابتلاهم اللهُ بنهرٍ فشرب أكثرُهم إلا قليلًا؛ فلمّا رأوا كثرة العدوّ استعظموه، وقال الموقنون بلقاء الله: كم من فئةٍ قليلةٍ غلبت كثيرةً بإذن الله، والله مع الصابرين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ النصر بإذن الله لا بالكثرة."},"action":{"text":"لا تنظرْ إلى قلّتك وكثرة خصمك؛ فالنصر بإذن الله والصبر."}},{"n":250,"reflection":{"text":"«ولما برزوا لجالوت وجنوده قالوا ربنا أفرغ علينا صبرا وثبت أقدامنا وانصرنا على القوم الكافرين» — دعاءُ الثبات عند لقاء العدوّ: صبرٌ يُفرَغ إفراغًا، وثباتُ أقدام، ونصرٌ على الكافرين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله بالدعاء عند الشدائد."},"action":{"text":"ادعُ عند كلّ شدّة: «ربنا أفرغ علينا صبرا وثبت أقدامنا»."}},{"n":251,"reflection":{"text":"«فهزموهم بإذن الله وقتل داود جالوت وآتاه الله الملك والحكمة وعلمه مما يشاء ولولا دفع الله الناس بعضهم ببعض لفسدت الأرض ولكن الله ذو فضل على العالمين» — نصرهم اللهُ فقتل داودُ جالوت، وآتاه الملك والنبوّة؛ ولولا أن يدفع اللهُ الظالمين بالمؤمنين لفسدت الأرض، لكنّه ذو فضلٍ على العالمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ سنّة التدافع التي بها يُحفظ الحقّ."},"action":{"text":"كنْ سببًا في دفع الباطل ونصرة الحقّ في موضعك."}},{"n":252,"reflection":{"text":"«تلك آيات الله نتلوها عليك بالحق وإنك لمن المرسلين» — هذه أخبارُ الغيب الصادقة من آيات الله يتلوها على نبيّه بالحقّ؛ وإنّه لمن المرسلين حقًّا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بصدق القرآن ورسالة النبيّ ﷺ."},"action":{"text":"تلقَّ أخبار القرآن بالتصديق واليقين، فهي الحقّ."}}]},{"title":"تفاضلُ الرسل، والإنفاقُ قبل فوات الأوان","range":[253,254],"theme":"منازلُ الأنبياء، والمبادرةُ بالبذل","verses":[{"n":253,"reflection":{"text":"«تلك الرسل فضلنا بعضهم على بعض منهم من كلم الله ورفع بعضهم درجات وآتينا عيسى ابن مريم البينات وأيدناه بروح القدس ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينات ولكن اختلفوا» — فضّل اللهُ الرسلَ بعضهم على بعض (كموسى المكلَّم وعيسى المؤيَّد بالآيات)؛ ولو شاء ما اقتتل الناس بعدهم، لكنّهم اختلفوا فآمن بعضٌ وكفر بعض، والله يفعل ما يريد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"محبّةُ الرسل جميعًا مع الإقرار بتفاضلهم."},"action":{"text":"أحبَّ أنبياء الله كلَّهم، وأنزلْ كلًّا منزلته التي أنزله الله."}},{"n":254,"reflection":{"text":"«يا أيها الذين آمنوا أنفقوا مما رزقناكم من قبل أن يأتي يوم لا بيع فيه ولا خلة ولا شفاعة والكافرون هم الظالمون» — بادروا بالإنفاق ممّا رزقكم الله قبل يومٍ لا ينفع فيه بيعٌ ولا صداقةٌ ولا شفاعةٌ إلا بإذنه؛ والكافرون هم الظالمون لأنفسهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالبذل قبل يوم لا ينفع فيه إلا العمل."},"action":{"text":"أنفقْ اليوم قبل يومٍ لا بيعَ فيه ولا شفاعةَ تنفعك."}}]},{"title":"آيةُ الكرسي — أعظمُ آيةٍ في القرآن","range":[255,255],"theme":"جماعُ التوحيد والأسماء والصفات","fadl":{"text":"أعظمُ آيةٍ في كتاب الله؛ ومن قرأها دبر كلِّ صلاةٍ مكتوبة لم يمنعه من دخول الجنة إلا أن يموت.","source":"صحيح مسلم (عن أبيّ بن كعب في عظمتها)، والنسائي وصحّحه ابن حبان (في قراءتها دبر الصلاة)","grade":"ma'thur"},"verses":[{"n":255,"reflection":{"text":"جمعت أصولَ التوحيد وأعظمَ الأسماء والصفات: تفرّدُه بالألوهية (لا إله إلا هو)، وكمالُ حياته وقيّوميّته (الحيُّ القيّوم)، وتنزّهُه عن النقص (لا تأخذه سِنةٌ ولا نوم)، وملكُه المطلق (له ما في السماوات والأرض)، وعظمتُه فلا شفاعة إلا بإذنه، وإحاطةُ علمه بكلِّ شيء، وسعةُ كرسيّه للسماوات والأرض، وأنّ حفظهما لا يُثقله، وعلوُّه وعظمته (وهو العليُّ العظيم).","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":["الله","الحي","القيوم","العلي","العظيم"],"heart_state":{"text":"امتلاءُ القلب بتعظيم الله وكمالِه، والافتقارِ إلى قيّوميّته."},"action":{"text":"اقرأها دبر كلِّ صلاةٍ وعند النوم متدبّرًا معناها، لا مجرّد لفظها."}}]},{"title":"لا إكراه في الدين، وولايةُ الله","range":[256,257],"theme":"العروةُ الوثقى، والخروجُ من الظلمات إلى النور","verses":[{"n":256,"sabab":{"text":"كانت المرأةُ من الأنصار لا يعيش لها ولدٌ فتنذر لتُهوّدنّه، فكان في بني النضير أبناءٌ للأنصار، فلمّا أُجليت أراد الأنصارُ إكراههم على الإسلام، فنزلت.","source":"رواه أبو داود والنسائي (عن ابن عباس)، وحسّنه غيرُ واحد","grade":"ma'thur"},"reflection":{"text":"«لا إكراه في الدين قد تبين الرشد من الغي فمن يكفر بالطاغوت ويؤمن بالله فقد استمسك بالعروة الوثقى لا انفصام لها والله سميع عليم» — لا يُكره أحدٌ على الدخول في الإسلام، فقد ظهرت الحجّة وتميّز الهدى من الضلال؛ ومن كفر بكلّ معبودٍ سوى الله وآمن به فقد تمسّك بأوثق عروةٍ لا تنقطع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["السميع","العليم"],"heart_state":{"text":"التمسّكُ بالتوحيد: كفرٌ بالطاغوت وإيمانٌ بالله."},"action":{"text":"جدّدْ عروتك الوثقى: اكفرْ بكلّ معبودٍ سوى الله، وأخلصْ إيمانك له."}},{"n":257,"reflection":{"text":"«الله ولي الذين آمنوا يخرجهم من الظلمات إلى النور والذين كفروا أولياؤهم الطاغوت يخرجونهم من النور إلى الظلمات أولئك أصحاب النار هم فيها خالدون» — اللهُ وليُّ المؤمنين يخرجهم من ظلمات الكفر والجهل والمعصية إلى نور الإيمان والعلم والطاعة؛ والكافرون أولياؤهم الطواغيت تخرجهم من النور إلى الظلمات.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الولي"],"heart_state":{"text":"الاعتزازُ بولاية الله، والخروجُ إلى نوره."},"action":{"text":"تولَّ الله بطاعته يخرجْك من كلّ ظلمةٍ إلى النور."}}]},{"title":"آياتُ الإحياء: إبراهيمُ والنمرود، والقرية، وطلبُ الطمأنينة","range":[258,260],"theme":"الحُجّةُ على البعث، وطمأنينةُ اليقين","verses":[{"n":258,"reflection":{"text":"«ألم تر إلى الذي حاج إبراهيم في ربه أن آتاه الله الملك إذ قال إبراهيم ربي الذي يحيي ويميت قال أنا أحيي وأميت قال إبراهيم فإن الله يأتي بالشمس من المشرق فأت بها من المغرب فبهت الذي كفر» — حاجّ النمرودُ إبراهيمَ كِبرًا بملكه؛ فلمّا احتجّ إبراهيم بالإحياء والإماتة موّه، فألزمه إبراهيمُ بأمر الشمس فانقطع وبُهت، فالله لا يهدي القوم الظالمين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحجّة، ووضوحُ برهان التوحيد."},"action":{"text":"تعلّمْ من إبراهيم قوّة الحجّة على التوحيد، وثباتَه بها."}},{"n":259,"reflection":{"text":"«أو كالذي مر على قرية وهي خاوية على عروشها قال أنى يحيي هذه الله بعد موتها فأماته الله مائة عام ثم بعثه... فلما تبين له قال أعلم أن الله على كل شيء قدير» — مرّ رجلٌ على قريةٍ خربة فاستبعد إحياءها، فأماته اللهُ مئة عام ثم بعثه، وأراه بقاء طعامه وشرابه وتغيّر حماره وإحياءه، وعظامَ حماره تُكسى لحمًا؛ فأيقن بقدرة الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["القدير"],"heart_state":{"text":"اليقينُ بقدرة الله على البعث بعد رؤية آياته."},"action":{"text":"قوِّ يقينك بالبعث بتأمّل إحياء الله للأرض والخلق."}},{"n":260,"reflection":{"text":"«وإذ قال إبراهيم رب أرني كيف تحيي الموتى قال أولم تؤمن قال بلى ولكن ليطمئن قلبي... فخذ أربعة من الطير فصرهن إليك ثم اجعل على كل جبل منهن جزءا ثم ادعهن يأتينك سعيا» — سأل إبراهيمُ رؤيةَ الإحياء لا شكًّا بل طلبًا لطمأنينة المعاينة؛ فأمره بأربعةٍ من الطير يقطّعها ويفرّقها ثم يدعوها فتأتيه سعيًا؛ فازداد يقينًا بأنّ الله عزيزٌ حكيم.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":["العزيز","الحكيم"],"heart_state":{"text":"طلبُ ازدياد اليقين بمعاينة آيات الله."},"action":{"text":"اطلبْ زيادة يقينك بالنظر في آيات الله، فطمأنينةُ القلب مطلوبة."}}]},{"title":"فضائلُ الإنفاق وآدابه","range":[261,274],"theme":"المضاعفةُ، وتركُ المنّ والرياء، والإنفاقُ من الطيّب","verses":[{"n":261,"reflection":{"text":"«مثل الذين ينفقون أموالهم في سبيل الله كمثل حبة أنبتت سبع سنابل في كل سنبلة مائة حبة والله يضاعف لمن يشاء والله واسع عليم» — مثلُ المنفق في سبيل الله كحبّةٍ أخرجت سبعمئة حبّة؛ والله يضاعف لمن يشاء فوق ذلك، واسعُ الفضل عليمٌ بمن يستحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الواسع","العليم"],"heart_state":{"text":"الرغبةُ في مضاعفة الله لأجر الإنفاق."},"action":{"text":"أنفقْ في سبيل الله موقنًا أنّ الحبّة الواحدة تصير سبعمئة وأكثر."}},{"n":262,"reflection":{"text":"«الذين ينفقون أموالهم في سبيل الله ثم لا يتبعون ما أنفقوا منا ولا أذى لهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون» — شرطُ قبول الإنفاق: ألّا يتبعه منٌّ على المُعطى ولا أذًى له؛ فلهؤلاء أجرُهم عند ربّهم، آمنين من الخوف والحزن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنفاقُ بلا منٍّ ولا أذى، حفظًا للأجر."},"action":{"text":"إذا تصدّقت فلا تمنَّ ولا تؤذِ من أعطيتَه، ولو بكلمة."}},{"n":263,"reflection":{"text":"«قول معروف ومغفرة خير من صدقة يتبعها أذى والله غني حليم» — كلمةٌ طيّبة وعفوٌ عن السائل خيرٌ من صدقةٍ يتبعها منٌّ وأذى؛ والله غنيٌّ عن صدقات عباده، حليمٌ لا يعجل بالعقوبة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغني","الحليم"],"heart_state":{"text":"تقديمُ الكلمة الطيّبة على العطاء المؤذي."},"action":{"text":"إن لم تعطِ فقلْ معروفًا؛ فالكلمة الطيّبة خيرٌ من عطاءٍ يجرح."}},{"n":264,"reflection":{"text":"«يا أيها الذين آمنوا لا تبطلوا صدقاتكم بالمن والأذى كالذي ينفق ماله رئاء الناس ولا يؤمن بالله واليوم الآخر فمثله كمثل صفوان عليه تراب فأصابه وابل فتركه صلدا» — نهيٌ عن إبطال الصدقة بالمنّ والأذى والرياء؛ فمثلُ المرائي كحجرٍ أملسَ عليه ترابٌ أذهبه المطر فتركه أجرد، لا يقدرون على شيءٍ ممّا كسبوا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإخلاصُ في الصدقة، والحذرُ من الرياء والمنّ."},"action":{"text":"أخلصْ صدقتك لله، ولا تُبطلْها برياءٍ أو منٍّ أو أذى."}},{"n":265,"reflection":{"text":"«ومثل الذين ينفقون أموالهم ابتغاء مرضاة الله وتثبيتا من أنفسهم كمثل جنة بربوة أصابها وابل فآتت أكلها ضعفين فإن لم يصبها وابل فطل والله بما تعملون بصير» — مثلُ المخلصين في الإنفاق كبستانٍ في مكانٍ مرتفعٍ خصب، يُثمر على كلّ حالٍ من مطرٍ كثيرٍ أو قليل؛ فعملُهم زاكٍ نامٍ مقبول.","source":"تفسير السعدي","grade":"ma'thur"},"names":["البصير"],"heart_state":{"text":"الإنفاقُ ابتغاءَ مرضاة الله وتثبيتًا للإيمان."},"action":{"text":"اجعلْ باعثك على الإنفاق مرضاةَ الله وتثبيتَ إيمانك."}},{"n":266,"reflection":{"text":"«أيود أحدكم أن تكون له جنة من نخيل وأعناب تجري من تحتها الأنهار له فيها من كل الثمرات وأصابه الكبر وله ذرية ضعفاء فأصابها إعصار فيه نار فاحترقت» — مثلٌ محذِّر: كمن له بستانٌ يحتاجه عند كبره وضعف ذرّيته فيحترق بريحٍ فيها نار؛ كذلك من يُبطل عمله بالمنّ والرياء يجده محترقًا أحوجَ ما يكون إليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من إحباط العمل يوم الحاجة إليه."},"action":{"text":"احرصْ ألّا تُحبطَ أعمالك؛ فتجدها ضائعةً أحوجَ ما تكون إليها."}},{"n":267,"reflection":{"text":"«يا أيها الذين آمنوا أنفقوا من طيبات ما كسبتم ومما أخرجنا لكم من الأرض ولا تيمموا الخبيث منه تنفقون ولستم بآخذيه إلا أن تغمضوا فيه واعلموا أن الله غني حميد» — أنفقوا من طيّب أموالكم لا من رديئها الذي لا ترضونه لأنفسكم؛ فالله غنيٌّ عن العطاء الخبيث، حميدٌ يستحقّ أطيبَ ما عندكم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الغني","الحميد"],"heart_state":{"text":"إعطاءُ الله أطيبَ المال لا أردأه."},"action":{"text":"تصدّقْ بما تحبّ وترضاه لنفسك، لا برديء مالك."}},{"n":268,"reflection":{"text":"«الشيطان يعدكم الفقر ويأمركم بالفحشاء والله يعدكم مغفرة منه وفضلا والله واسع عليم» — الشيطانُ يخوّفكم الفقرَ ليمنعكم الإنفاق، ويأمركم بالبخل والمعاصي؛ والله يعدكم على الإنفاق مغفرةً وفضلًا (خلَفًا وزيادة)، واسعُ الفضل عليم.","source":"تفسير السعدي","grade":"ma'thur"},"names":["الواسع","العليم"],"heart_state":{"text":"تصديقُ وعد الله، وتكذيبُ وعيد الشيطان بالفقر."},"action":{"text":"إذا خوّفك الشيطان الفقرَ عند الصدقة فأنفقْ، وثِقْ بوعد الله بالخلَف."}},{"n":269,"reflection":{"text":"«يؤتي الحكمة من يشاء ومن يؤت الحكمة فقد أوتي خيرا كثيرا وما يذكر إلا أولو الألباب» — الحكمةُ (الإصابةُ في القول والعمل، وفقهُ الدين) عطاءٌ من الله؛ ومن أُوتيها فقد أُوتي خيرًا كثيرًا، ولا يتّعظ بذلك إلا أصحاب العقول.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الحكمة من الله، فهي خيرٌ كثير."},"action":{"text":"اسألِ الله الحكمة والفقه في الدين، واعملْ بما علمت."}},{"n":270,"reflection":{"text":"«وما أنفقتم من نفقة أو نذرتم من نذر فإن الله يعلمه وما للظالمين من أنصار» — كلُّ نفقةٍ أو نذرٍ يعلمه اللهُ فيجزي عليه إن كان في طاعته؛ ومن ظلم بمنع الحقّ أو الإنفاق في معصيةٍ فلا ناصر له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ علم الله بكلّ نفقةٍ ونذر."},"action":{"text":"أوفِ بنذرك في الطاعة، وأنفقْ محتسبًا، فالله يعلم ويجزي."}},{"n":271,"reflection":{"text":"«إن تبدوا الصدقات فنعما هي وإن تخفوها وتؤتوها الفقراء فهو خير لكم ويكفر عنكم من سيئاتكم والله بما تعملون خبير» — إظهارُ الصدقة حسنٌ، وإخفاؤها وإيتاؤها الفقراء أفضلُ وأبعدُ عن الرياء وأدعى لتكفير السيئات؛ والله خبيرٌ بما تعملون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["الخبير"],"heart_state":{"text":"إيثارُ إخفاء الصدقة إبعادًا للرياء."},"action":{"text":"أخفِ صدقتك ما استطعت؛ فالسرُّ فيها أطهرُ وأعظمُ أجرًا."}},{"n":272,"reflection":{"text":"«ليس عليك هداهم ولكن الله يهدي من يشاء وما تنفقوا من خير فلأنفسكم وما تنفقون إلا ابتغاء وجه الله وما تنفقوا من خير يوف إليكم وأنتم لا تظلمون» — ليس عليك هدايةُ الناس بل عليك البلاغ؛ والإنفاقُ نفعُه لكم، فليكنْ لوجه الله؛ وما تنفقوه يُوفَّ إليكم بلا نقص.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإنفاقُ لوجه الله، وتفويضُ الهداية إليه."},"action":{"text":"أنفقْ لوجه الله ولو على غير المسلم المحتاج، ودعِ الهداية لله."}},{"n":273,"reflection":{"text":"«للفقراء الذين أحصروا في سبيل الله لا يستطيعون ضربا في الأرض يحسبهم الجاهل أغنياء من التعفف تعرفهم بسيماهم لا يسألون الناس إلحافا» — أولى الناس بالصدقة فقراءُ حبسوا أنفسهم في طاعة الله لا يقدرون على التكسّب، يظنّهم الجاهلُ أغنياء لتعفّفهم، تعرفهم بعلامتهم، لا يُلحّون في السؤال.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تحرّي المتعفّفين المحتاجين بالصدقة."},"action":{"text":"ابحثْ عن الفقير المتعفّف الذي لا يسأل، فهو أولى بصدقتك."}},{"n":274,"reflection":{"text":"«الذين ينفقون أموالهم بالليل والنهار سرا وعلانية فلهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون» — من داوم على الإنفاق في كلّ وقتٍ وحال، سرًّا وعلانيةً، فله أجرُه عند ربّه، آمنًا من الخوف والحزن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المداومةُ على الإنفاق في كلّ حال."},"action":{"text":"اجعلْ لك صدقةً دائمة ولو قلّت، سرًّا وعلانية."}}]},{"title":"تحريمُ الربا، وإنظارُ المعسر، والمحاسبة","range":[275,284],"theme":"شناعةُ الربا، وبركةُ الصدقة، وحفظُ الحقوق","verses":[{"n":275,"reflection":{"text":"«الذين يأكلون الربا لا يقومون إلا كما يقوم الذي يتخبطه الشيطان من المس ذلك بأنهم قالوا إنما البيع مثل الربا وأحل الله البيع وحرم الربا» — آكلُ الربا يُبعث يوم القيامة يتخبّط كالمصروع؛ عقوبةً على مساواتهم البيعَ بالربا؛ وقد أحلّ اللهُ البيع وحرّم الربا؛ فمن انتهى فله ما سلف، ومن عاد فأصحاب النار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استعظامُ جرم الربا واجتنابُه."},"action":{"text":"اجتنبِ الربا أخذًا وإعطاءً وكتابةً وشهادة، فهو من الموبقات."}},{"n":276,"reflection":{"text":"«يمحق الله الربا ويربي الصدقات والله لا يحب كل كفار أثيم» — يمحق اللهُ بركةَ مال الربا ويُهلكه، ويُنمّي الصدقاتِ ويبارك فيها؛ ولا يحبّ من أصرّ على كفران النعمة وارتكاب الإثم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ البركة في الصدقة لا في الربا."},"action":{"text":"أنمِ مالك بالصدقة لا بالربا؛ فالله يمحق ذاك ويبارك في هذا."}},{"n":277,"reflection":{"text":"«إن الذين آمنوا وعملوا الصالحات وأقاموا الصلاة وآتوا الزكاة لهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون» — أهلُ الإيمان والعمل الصالح والصلاة والزكاة لهم أجرُهم عند ربّهم، آمنين من الخوف والحزن — في مقابل آكلي الربا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرجاءُ في أجر الله لأهل الإيمان والزكاة."},"action":{"text":"أقمِ الصلاة وآتِ الزكاة؛ فذاك سبيلُ الأمن من الخوف والحزن."}},{"n":278,"reflection":{"text":"«يا أيها الذين آمنوا اتقوا الله وذروا ما بقي من الربا إن كنتم مؤمنين» — أمرٌ بتقوى الله وترك ما بقي من معاملات الربا؛ وجعل ذلك من مقتضى الإيمان الصادق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أن يكون تركُ الربا من صدق الإيمان."},"action":{"text":"تخلَّصْ من كلّ معاملةٍ رِبويّة بقيت لك؛ فذاك من الإيمان."}},{"n":279,"reflection":{"text":"«فإن لم تفعلوا فأذنوا بحرب من الله ورسوله وإن تبتم فلكم رؤوس أموالكم لا تظلمون ولا تظلمون» — إن لم تتركوا الربا فقد آذنتم بحربٍ من الله ورسوله؛ وإن تبتم فلكم رأسُ مالكم فقط، لا تَظلمون بأخذ الزيادة ولا تُظلمون بنقص أصلكم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الخوفُ من محاربة الله، والعدلُ في المعاملة."},"action":{"text":"دعِ الربا فورًا؛ فلا خيرَ في مالٍ سببه حربُ الله ورسوله."}},{"n":280,"reflection":{"text":"«وإن كان ذو عسرة فنظرة إلى ميسرة وأن تصدقوا خير لكم إن كنتم تعلمون» — إن كان المدينُ معسرًا فأنظِروه إلى يُسر؛ وأن تتصدّقوا عليه بإسقاط الدَّين أو بعضه خيرٌ لكم لو تعلمون فضله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الرحمةُ بالمعسر، وإيثارُ الإحسان إليه."},"action":{"text":"أنظِرْ من أعسر عليك، وإن سمحتَ بدَينك فذاك خيرٌ لك."}},{"n":281,"reflection":{"text":"«واتقوا يوما ترجعون فيه إلى الله ثم توفى كل نفس ما كسبت وهم لا يظلمون» — تحذيرٌ عظيم: اتّقوا يومًا ترجعون فيه إلى الله فتُوفّى كلُّ نفسٍ جزاءَ ما كسبت بلا ظلم. قيل: هي من آخر ما نزل من القرآن.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"استحضارُ يوم الرجوع إلى الله والجزاء."},"action":{"text":"زِنْ كلّ عملٍ بميزان يومٍ ترجع فيه إلى الله فتُوفّى كسبك."}},{"n":282,"reflection":{"text":"«يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه وليكتب بينكم كاتب بالعدل... واستشهدوا شهيدين من رجالكم» — أطولُ آيةٍ في القرآن: أمرٌ بكتابة الدَّين المؤجّل والإشهاد عليه حفظًا للحقوق ودفعًا للنزاع والريبة؛ رحمةً وتيسيرًا. وأمرَ بالتقوى في ذلك.","source":"تفسير ابن كثير والسعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"حفظُ الحقوق بالتوثيق، واتّقاءُ النزاع."},"action":{"text":"وثّقْ ديونك ومعاملاتك بالكتابة والإشهاد؛ فذاك أحفظُ للحقّ."}},{"n":283,"reflection":{"text":"«وإن كنتم على سفر ولم تجدوا كاتبا فرهان مقبوضة فإن أمن بعضكم بعضا فليؤد الذي اؤتمن أمانته وليتق الله ربه ولا تكتموا الشهادة ومن يكتمها فإنه آثم قلبه» — إن تعذّرت الكتابةُ في السفر فالرهنُ المقبوض؛ وإن ائتمن بعضُكم بعضًا فليؤدِّ الأمين أمانته وليتّقِ الله؛ ولا تكتموا الشهادة، فكاتمُها آثمُ القلب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"أداءُ الأمانة، وعدمُ كتمان الشهادة."},"action":{"text":"أدِّ الأمانة التي اؤتمنتَ عليها، ولا تكتمْ شهادةً عندك."}},{"n":284,"sabab":{"text":"لمّا نزلت «وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله» شقّ ذلك على الصحابة وقالوا: كُلّفنا ما لا نطيق من حديث النفس! فأنزل اللهُ بعدها التخفيف: «لا يكلّف الله نفسًا إلا وسعها»، ونُسخت مؤاخذةُ حديث النفس.","source":"صحيح مسلم (عن أبي هريرة)","grade":"ma'thur"},"reflection":{"text":"«لله ما في السماوات وما في الأرض وإن تبدوا ما في أنفسكم أو تخفوه يحاسبكم به الله فيغفر لمن يشاء ويعذب من يشاء والله على كل شيء قدير» — له ملكُ السماوات والأرض وعلمُ ما في النفوس؛ يحاسب على ما تُبدون وتُخفون، فيغفر لمن يشاء ويعذّب من يشاء. ولمّا شقّ ذلك على الصحابة نزل التخفيفُ بعدها (لا يكلّف الله نفسًا إلا وسعها).","source":"تفسير ابن كثير","grade":"ma'thur"},"names":["القدير"],"heart_state":{"text":"مراقبةُ الله في السرّ، ورجاءُ مغفرته."},"action":{"text":"طهّرْ سريرتك كما تطهّر علانيتك؛ فالله يعلم ما في نفسك."}}]},{"title":"خواتيمُ البقرة — آمنَ الرسول","range":[285,286],"theme":"إقرارُ الإيمان، ودعاءٌ جامعٌ أُجيب","fadl":{"text":"من قرأ بالآيتين من آخر سورة البقرة في ليلةٍ كفتاه.","source":"متّفقٌ عليه (البخاري ومسلم عن أبي مسعود)","grade":"ma'thur"},"verses":[{"n":285,"reflection":{"text":"أقرَّ الرسولُ ﷺ والمؤمنون بالإيمان بالله وملائكته وكتبه ورسله، لا يفرّقون بين أحدٍ من رسله، وقالوا مسلِّمين منقادين: «سمعنا وأطعنا»، ثم افتقروا إلى مغفرته: «غفرانك ربّنا وإليك المصير».","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الانقيادُ التامّ: سمعنا وأطعنا، مع الافتقار إلى المغفرة."},"action":{"text":"اجعلْ شعارك عند أمر الله ونهيه: «سمعنا وأطعنا»، لا «سمعنا ثم نرى»."}},{"n":286,"reflection":{"text":"من رحمته أنّه لا يكلّف نفسًا إلا وسعها، ولكلٍّ كسبُه، ثم علّمنا دعاءً جامعًا: رفعِ المؤاخذة بالنسيان والخطأ، وألّا يحمل علينا إصرًا كمن قبلنا، ولا ما لا طاقة لنا به، والعفوِ والمغفرةِ والرحمةِ والنصر. وقد قال اللهُ عقب كلِّ مسألةٍ منها: «قد فعلت».","source":"تفسير ابن كثير والسعدي؛ وصحيح مسلم (في «قد فعلت»)","grade":"ma'thur"},"names":[],"heart_state":{"text":"الطمأنينةُ إلى سعة رحمة الله ويُسر تكليفه، والرجاءُ في إجابة دعائه."},"action":{"text":"ادعُ الليلةَ بهذا الدعاء متدبّرًا، موقنًا أنّ الله قال في كلِّ مسألةٍ منه: قد فعلت."}}]}],"coverage":{"covered":286,"total":286}};
